/* 자동 생성 — tools/motto-build.cjs. '오늘의 한 칸' 카드 문구 100개 (2026-11-20). 1~75 하루칸 문구, 76~100 명언(by = 출처) */
export const MOTTO = [{"id":1,"t":{"ko":"한 줄이면 충분해요. 오늘 한 칸만 채워 볼까요?","en":"One line is enough. Want to fill in today’s box?","ja":"一行で十分。今日のマスを埋めてみませんか？","zh":"一行就够了。来填今天的格子吧？","es":"Con una línea basta. ¿Llenamos la casilla de hoy?","pt":"Uma linha já basta. Que tal preencher o quadrinho de hoje?","th":"แค่บรรทัดเดียวก็พอ วันนี้มาเติมสักช่องกันไหม","ar":"سطر واحد يكفي. هل نملأ خانة اليوم؟","tr":"Bir satır yeter. Bugün tek bir kutuyu dolduralım mı?","de":"Eine Zeile reicht. Magst du dein Feld heute füllen?","fr":"Une ligne suffit. Et si vous remplissiez la case du jour ?","nl":"Eén regel is genoeg. Vul je het vakje van vandaag?","pl":"Jedna linijka wystarczy. Wypełnisz dziś jedną kratkę?","ro":"Un rând e de ajuns. Completezi azi o căsuță?"}},{"id":2,"t":{"ko":"잘 쓰지 않아도 괜찮아요. 쓰는 것만으로 충분해요.","en":"It doesn’t have to be good. Just writing is enough.","ja":"上手に書けなくても大丈夫。書くだけで十分です。","zh":"写得不好也没关系，写下来就够了。","es":"No tiene que estar bien escrito. Basta con escribir.","pt":"Não precisa escrever bem. Só escrever já basta.","th":"เขียนไม่เก่งก็ไม่เป็นไร แค่ได้เขียนก็พอแล้ว","ar":"لا بأس إن لم تُتقن الكتابة. يكفي أنك تكتب.","tr":"İyi yazmak zorunda değilsin. Yazman yeterli.","de":"Es muss nicht perfekt sein. Schreiben allein reicht schon.","fr":"Pas besoin de bien écrire. Écrire, c’est déjà beaucoup.","nl":"Het hoeft niet mooi te zijn. Schrijven is al genoeg.","pl":"Nie musi być pięknie. Wystarczy, że piszesz.","ro":"Nu trebuie să fie perfect. Ajunge să scrii."}},{"id":3,"t":{"ko":"오늘 있었던 일 하나만 적어 볼까요?","en":"How about writing down one thing from today?","ja":"今日あったことを、ひとつだけ書いてみませんか？","zh":"要不要写下今天发生的一件事？","es":"¿Anotamos una sola cosa que pasó hoy?","pt":"Que tal anotar uma coisa que aconteceu hoje?","th":"ลองเขียนเรื่องที่เกิดขึ้นวันนี้สักเรื่องไหม","ar":"هل تكتب شيئًا واحدًا حدث اليوم؟","tr":"Bugün olan tek bir şeyi yazalım mı?","de":"Schreib doch eine Sache auf, die heute passiert ist.","fr":"Et si vous notiez une seule chose de votre journée ?","nl":"Schrijf eens één ding op dat vandaag is gebeurd.","pl":"Zapisz jedną rzecz, która się dziś wydarzyła.","ro":"Scrie un singur lucru care s-a întâmplat azi."}},{"id":4,"t":{"ko":"1분이면 돼요. 오늘의 나를 남겨요.","en":"One minute is all it takes. Capture who you are today.","ja":"1分でOK。今日の自分を残しましょう。","zh":"只要一分钟，留下今天的自己。","es":"Basta con un minuto. Deja huella de tu yo de hoy.","pt":"Só leva um minuto. Guarde quem você é hoje.","th":"แค่ 1 นาทีก็พอ เก็บตัวเราในวันนี้ไว้นะ","ar":"دقيقة واحدة تكفي. اترك أثرًا منك اليوم.","tr":"Bir dakika yeter. Bugünkü seni kaydet.","de":"Eine Minute genügt. Halte dein Heute fest.","fr":"Une minute suffit. Gardez une trace de qui vous êtes aujourd’hui.","nl":"Eén minuutje is genoeg. Leg vast wie je vandaag bent.","pl":"Wystarczy minuta. Zostaw ślad dzisiejszego dnia.","ro":"Ajunge un minut. Lasă o urmă a zilei de azi."}},{"id":5,"t":{"ko":"거창하지 않아도 돼요. 오늘의 한 단어부터.","en":"No need for anything big. Start with one word.","ja":"大げさに書かなくていいんです。今日のひと言から。","zh":"不必写得多精彩，从今天的一个词开始。","es":"No tiene que ser algo grande. Empieza con una palabra.","pt":"Não precisa ser nada grandioso. Comece com uma palavra.","th":"ไม่ต้องยิ่งใหญ่ก็ได้ เริ่มจากคำเดียวของวันนี้","ar":"لا داعي لشيء كبير. ابدأ بكلمة واحدة عن اليوم.","tr":"Büyük laflara gerek yok. Tek bir kelimeyle başla.","de":"Es muss nichts Großes sein. Fang mit einem Wort an.","fr":"Pas besoin de grandes phrases. Commencez par un mot.","nl":"Het hoeft niet groots te zijn. Begin met één woord.","pl":"Nie musi to być nic wielkiego. Zacznij od jednego słowa.","ro":"Nu trebuie să fie ceva măreț. Începe cu un cuvânt."}},{"id":6,"t":{"ko":"지금 떠오르는 기분을 그대로 적어 봐요.","en":"Write down how you feel right now, just as it is.","ja":"今の気持ちを、そのまま書いてみましょう。","zh":"把此刻的心情原原本本写下来吧。","es":"Escribe tal cual lo que sientes ahora.","pt":"Escreva do jeitinho que você está se sentindo agora.","th":"ลองเขียนความรู้สึกตอนนี้ออกมาตามจริง","ar":"اكتب شعورك الآن كما هو.","tr":"Şu an içinden geçeni olduğu gibi yaz.","de":"Schreib einfach auf, wie du dich gerade fühlst.","fr":"Écrivez simplement ce que vous ressentez maintenant.","nl":"Schrijf op hoe je je nu voelt, gewoon zoals het is.","pl":"Zapisz, co teraz czujesz, tak po prostu.","ro":"Scrie exact ce simți acum."}},{"id":7,"t":{"ko":"오늘 먹은 것 하나만 적어도 일기예요.","en":"Even one thing you ate today counts as a diary.","ja":"今日食べたものひとつでも、立派な日記です。","zh":"哪怕只写今天吃了什么，也算日记。","es":"Anotar algo que comiste hoy ya es un diario.","pt":"Anotar algo que você comeu hoje já é um diário.","th":"แค่จดเมนูที่กินวันนี้สักอย่าง ก็เป็นไดอารี่แล้ว","ar":"يكفي أن تكتب عن طعام واحد تناولته اليوم، فهذه يوميات أيضًا.","tr":"Bugün yediğin tek bir şeyi yazsan bile, o da günlük sayılır.","de":"Schon eine Zeile über dein Essen ist ein Tagebucheintrag.","fr":"Noter simplement ce que vous avez mangé, c’est déjà tenir un journal.","nl":"Eén regel over wat je vandaag at, telt ook als dagboek.","pl":"Nawet jedna linijka o dzisiejszym jedzeniu to już dziennik.","ro":"Chiar și un rând despre ce ai mâncat azi e tot jurnal."}},{"id":8,"t":{"ko":"빈칸보다 한 줄이 나아요.","en":"One line beats an empty box.","ja":"空白より、一行のほうがいい。","zh":"写一行，总比空着好。","es":"Mejor una línea que una casilla vacía.","pt":"Uma linha é melhor que um quadrinho vazio.","th":"หนึ่งบรรทัดดีกว่าช่องว่างเปล่า","ar":"سطر واحد أفضل من خانة فارغة.","tr":"Bir satır, boş bir kutudan iyidir.","de":"Eine Zeile ist besser als ein leeres Feld.","fr":"Mieux vaut une ligne qu’une case vide.","nl":"Eén regel is beter dan een leeg vakje.","pl":"Jedna linijka jest lepsza niż pusta kratka.","ro":"Mai bine un rând decât o căsuță goală."}},{"id":9,"t":{"ko":"오늘의 날씨처럼 오늘의 마음도 적어 볼까요?","en":"Like the weather, why not note today’s mood too?","ja":"今日の天気のように、今日の気持ちも書いてみませんか？","zh":"像记下天气一样，也记下今天的心情吧？","es":"Como el clima de hoy, ¿anotamos también cómo te sientes?","pt":"Assim como o clima de hoje, que tal anotar como você está?","th":"เหมือนจดสภาพอากาศ ลองจดอารมณ์ของวันนี้ไว้ด้วยไหม","ar":"كما تكتب طقس اليوم، هل تكتب مزاجك أيضًا؟","tr":"Bugünün havası gibi, bugünün ruh halini de yazalım mı?","de":"Nicht nur das Wetter: Wie war deine Stimmung heute?","fr":"Comme la météo, notez votre humeur du jour.","nl":"Niet alleen het weer: hoe was jouw stemming vandaag?","pl":"Zapisz dziś nie tylko pogodę, ale i swój nastrój.","ro":"Pe lângă vreme, notează și starea ta de azi."}},{"id":10,"t":{"ko":"사진 한 장과 한 줄이면 오늘이 남아요.","en":"One photo and one line, and today stays with you.","ja":"写真一枚と一行で、今日が残ります。","zh":"一张照片加一行字，今天就留下来了。","es":"Una foto y una línea, y el día queda guardado.","pt":"Uma foto e uma linha, e o dia fica guardado.","th":"รูปสักใบกับอีกหนึ่งบรรทัด ก็เก็บวันนี้ไว้ได้แล้ว","ar":"صورة واحدة وسطر واحد يحفظان يومك.","tr":"Bir fotoğraf ve bir satırla bugün kalıcı olur.","de":"Ein Foto, eine Zeile – und der Tag bleibt.","fr":"Une photo, une ligne, et la journée reste.","nl":"Eén foto en één regel, en je dag blijft bewaard.","pl":"Wystarczy zdjęcie i jedna linijka, by zachować dzień.","ro":"O poză și un rând, și ziua rămâne."}},{"id":11,"t":{"ko":"완벽한 문장 말고, 솔직한 한 줄.","en":"Not a perfect sentence. Just an honest line.","ja":"完璧な文章より、素直な一行を。","zh":"不求完美的句子，只要真诚的一行。","es":"No una frase perfecta, sino una línea sincera.","pt":"Nada de frase perfeita: uma linha sincera.","th":"ไม่ต้องเป็นประโยคที่สมบูรณ์ แค่หนึ่งบรรทัดที่จริงใจ","ar":"لا جملة مثالية، بل سطر صادق.","tr":"Kusursuz cümleler değil, içten bir satır.","de":"Kein perfekter Satz, nur eine ehrliche Zeile.","fr":"Pas une phrase parfaite : une ligne sincère.","nl":"Geen perfecte zin, maar één eerlijke regel.","pl":"Nie idealne zdanie, tylko jedna szczera linijka.","ro":"Nu o frază perfectă, ci un rând sincer."}},{"id":12,"t":{"ko":"쓰다 보면 생각이 정리돼요. 첫 줄만 써 봐요.","en":"Writing sorts out your thoughts. Just write the first line.","ja":"書くうちに考えが整理されます。まずは一行目だけ。","zh":"写着写着思路就清楚了。先写第一行吧。","es":"Escribir ordena las ideas. Empieza por la primera línea.","pt":"Escrever organiza os pensamentos. Comece pela primeira linha.","th":"เขียนไปเรื่อยๆ ความคิดจะเรียบเรียงเอง ลองเริ่มบรรทัดแรกดูนะ","ar":"الكتابة ترتّب أفكارك. اكتب السطر الأول فقط.","tr":"Yazdıkça düşüncelerin toparlanır. Sadece ilk satırı yaz.","de":"Schreiben ordnet die Gedanken. Fang mit der ersten Zeile an.","fr":"Écrire aide à y voir clair. Écrivez juste la première ligne.","nl":"Schrijven ordent je gedachten. Begin met de eerste regel.","pl":"Pisanie porządkuje myśli. Zacznij od pierwszej linijki.","ro":"Scrisul îți ordonează gândurile. Începe cu primul rând."}},{"id":13,"t":{"ko":"오늘을 세 단어로 말한다면?","en":"What three words would sum up today?","ja":"今日を3つの言葉で表すなら？","zh":"如果用三个词形容今天，会是什么？","es":"¿Cómo describirías tu día en tres palabras?","pt":"Como você descreveria o seu dia em três palavras?","th":"ถ้าให้เล่าวันนี้ด้วยสามคำล่ะ","ar":"كيف تصف يومك بثلاث كلمات؟","tr":"Bugünü üç kelimeyle anlatsan?","de":"Dein Tag in drei Wörtern?","fr":"Votre journée en trois mots ?","nl":"Je dag in drie woorden?","pl":"Twój dzień w trzech słowach?","ro":"Ziua de azi în trei cuvinte?"}},{"id":14,"t":{"ko":"지금 이 순간을 한 칸에 담아 두세요.","en":"Capture this very moment in a box.","ja":"この瞬間を、ひとつのマスに残しておきましょう。","zh":"把此刻装进一格里吧。","es":"Guarda este momento en una casilla.","pt":"Guarde este momento num quadrinho.","th":"เก็บช่วงเวลานี้ไว้ในหนึ่งช่องนะ","ar":"احفظ هذه اللحظة في خانة واحدة.","tr":"Bu anı tek bir kutuya sakla.","de":"Halte diesen Moment in deinem Feld fest.","fr":"Gardez cet instant dans une case.","nl":"Vang dit moment in één vakje.","pl":"Zamknij tę chwilę w jednej kratce.","ro":"Păstrează clipa asta într-o căsuță."}},{"id":15,"t":{"ko":"잠들기 전 1분, 오늘에게 인사해요.","en":"One minute before bed. Say goodnight to today.","ja":"寝る前の1分、今日にあいさつを。","zh":"睡前一分钟，跟今天道声晚安。","es":"Un minuto antes de dormir para despedirte del día.","pt":"Um minuto antes de dormir para se despedir do dia.","th":"1 นาทีก่อนนอน มาบอกลาวันนี้กัน","ar":"دقيقة قبل النوم، ودِّع فيها يومك.","tr":"Uyumadan önce bir dakika ayır, bugünle vedalaş.","de":"Eine Minute vorm Schlafengehen: Sag deinem Tag gute Nacht.","fr":"Une minute avant de dormir pour dire bonsoir à la journée.","nl":"Eén minuut voor het slapen: zeg je dag welterusten.","pl":"Minuta przed snem: powiedz dzisiejszemu dniu dobranoc.","ro":"Un minut înainte de somn: spune-i noapte bună zilei de azi."}},{"id":16,"t":{"ko":"오늘의 한 칸은 내일의 나에게 남기는 쪽지예요.","en":"Today’s box is a note to tomorrow’s you.","ja":"今日のマスは、明日の自分へのメモです。","zh":"今天这一格，是留给明天自己的小纸条。","es":"La casilla de hoy es una nota para tu yo de mañana.","pt":"O quadrinho de hoje é um bilhete para o você de amanhã.","th":"ช่องของวันนี้คือโน้ตที่ฝากไว้ให้ตัวเราในวันพรุ่งนี้","ar":"خانة اليوم رسالة صغيرة تتركها لنفسك في الغد.","tr":"Bugünün kutusu, yarınki sana bıraktığın bir not.","de":"Dein Feld heute ist ein Zettel an dein Ich von morgen.","fr":"La case du jour est un petit mot pour vous-même, demain.","nl":"Het vakje van vandaag is een briefje voor jezelf van morgen.","pl":"Dzisiejsza kratka to liścik dla siebie na jutro.","ro":"Căsuța de azi e un bilețel pentru tine, pentru mâine."}},{"id":17,"t":{"ko":"맞춤법은 신경 쓰지 마세요. 나만 보는 일기니까.","en":"Don’t worry about spelling. It’s just for you.","ja":"誤字は気にしないで。自分だけの日記だから。","zh":"别在意错别字，反正只有你自己看。","es":"No te preocupes por la ortografía. Este diario es solo para ti.","pt":"Não se preocupe com a ortografia. Este diário é só seu.","th":"ไม่ต้องห่วงเรื่องสะกดผิด เพราะไดอารี่นี้มีแค่เราที่อ่าน","ar":"لا تقلق بشأن الأخطاء الإملائية، فهذه يومياتك وحدك.","tr":"Yazım hatalarını dert etme. Bu günlüğü sadece sen okuyorsun.","de":"Rechtschreibung ist egal – dieses Tagebuch liest nur du.","fr":"Oubliez l’orthographe : ce journal n’est que pour vous.","nl":"Let niet op spelling. Alleen jij leest dit dagboek.","pl":"Nie przejmuj się ortografią. Ten dziennik czytasz tylko ty.","ro":"Nu-ți face griji pentru ortografie. Jurnalul ăsta e doar al tău."}},{"id":18,"t":{"ko":"아무 일 없던 하루도 남길 가치가 있어요.","en":"Even an uneventful day is worth keeping.","ja":"何もなかった一日も、残す価値があります。","zh":"平平无奇的一天，也值得留下。","es":"Hasta un día en que no pasó nada merece quedar escrito.","pt":"Até um dia sem nada de especial merece ser registrado.","th":"แม้จะเป็นวันที่ไม่มีอะไรเกิดขึ้น ก็มีค่าพอให้เก็บไว้","ar":"حتى يوم بلا أحداث يستحق أن يُدوَّن.","tr":"Hiçbir şeyin olmadığı bir gün de kaydetmeye değer.","de":"Auch ein ereignisloser Tag verdient sein Feld.","fr":"Même une journée sans histoire mérite d’être gardée.","nl":"Ook een dag zonder iets bijzonders is het bewaren waard.","pl":"Nawet dzień, w którym nic się nie stało, warto zapisać.","ro":"Și o zi fără nimic special merită păstrată."}},{"id":19,"t":{"ko":"짧아도 돼요. 한 줄이 쌓이면 한 해가 돼요.","en":"Short is fine. Line by line, it adds up to a year.","ja":"短くていいんです。一行が積み重なって一年になります。","zh":"短一点也没关系，一行行积累起来就是一年。","es":"Puede ser breve. Línea a línea se forma un año.","pt":"Pode ser curtinho. Linha por linha, vira um ano.","th":"สั้นๆ ก็ได้ บรรทัดที่สะสมไว้จะกลายเป็นหนึ่งปี","ar":"لا بأس بالقِصَر. السطور حين تتراكم تصبح عامًا.","tr":"Kısa olabilir. Satırlar birikince bir yıl olur.","de":"Kurz ist okay. Zeile für Zeile wird daraus ein Jahr.","fr":"Court, c’est très bien. Ligne après ligne, une année se construit.","nl":"Kort mag. Regel voor regel wordt het een heel jaar.","pl":"Krótko też jest dobrze. Z linijek uzbiera się cały rok.","ro":"Poate fi scurt. Rând cu rând, se adună un an."}},{"id":20,"t":{"ko":"오늘 가장 기억에 남는 장면 하나는?","en":"What scene from today stands out the most?","ja":"今日いちばん心に残った場面は？","zh":"今天最难忘的一个画面是？","es":"¿Qué escena de hoy recuerdas más?","pt":"Qual cena de hoje mais ficou na sua memória?","th":"ภาพไหนของวันนี้ที่ยังจำได้ชัดที่สุด","ar":"أيّ مشهد من اليوم بقي في ذاكرتك أكثر؟","tr":"Bugün aklında en çok kalan an hangisi?","de":"Welcher Moment von heute bleibt dir in Erinnerung?","fr":"Quel moment de la journée vous a le plus marqué ?","nl":"Welk moment van vandaag is je het meest bijgebleven?","pl":"Która dzisiejsza chwila najbardziej zapadła ci w pamięć?","ro":"Ce moment de azi ți-a rămas cel mai mult în minte?"}},{"id":21,"t":{"ko":"오늘 나를 웃게 한 건 뭐였나요?","en":"What made you smile today?","ja":"今日、あなたを笑顔にしたものは？","zh":"今天是什么让你笑了？","es":"¿Qué te hizo sonreír hoy?","pt":"O que fez você sorrir hoje?","th":"วันนี้อะไรทำให้เรายิ้มได้","ar":"ما الذي أضحكك اليوم؟","tr":"Bugün seni ne gülümsetti?","de":"Was hat dich heute zum Lachen gebracht?","fr":"Qu’est-ce qui vous a fait sourire aujourd’hui ?","nl":"Waar moest je vandaag om lachen?","pl":"Co cię dziś rozśmieszyło?","ro":"Ce te-a făcut să râzi azi?"}},{"id":22,"t":{"ko":"오늘 고마웠던 사람이 있나요?","en":"Was there someone you felt thankful for today?","ja":"今日、感謝したい人はいましたか？","zh":"今天有想感谢的人吗？","es":"¿Hubo alguien a quien agradecer hoy?","pt":"Tem alguém a quem você quer agradecer hoje?","th":"วันนี้มีใครที่อยากขอบคุณไหม","ar":"هل هناك شخص تشعر بالامتنان له اليوم؟","tr":"Bugün teşekkür etmek istediğin biri var mı?","de":"Gab es heute jemanden, dem du dankbar bist?","fr":"Y a-t-il quelqu’un à remercier aujourd’hui ?","nl":"Is er iemand die je vandaag dankbaar bent?","pl":"Czy jest ktoś, komu chcesz dziś podziękować?","ro":"Cui vrei să-i mulțumești azi?"}},{"id":23,"t":{"ko":"오늘 잘한 일 하나를 칭찬해 줘요.","en":"Give yourself credit for one thing you did well today.","ja":"今日うまくできたことを、ひとつほめてあげましょう。","zh":"夸夸今天做得好的一件事吧。","es":"Felicítate por algo que hiciste bien hoy.","pt":"Elogie algo que você fez bem hoje.","th":"ชมตัวเองสักเรื่องที่ทำได้ดีในวันนี้","ar":"امدح نفسك على شيء أحسنت فعله اليوم.","tr":"Bugün iyi yaptığın bir şey için kendini öv.","de":"Lob dich für eine Sache, die heute gut lief.","fr":"Félicitez-vous pour une chose réussie aujourd’hui.","nl":"Geef jezelf een compliment voor iets wat vandaag goed ging.","pl":"Pochwal siebie za coś, co ci dziś wyszło.","ro":"Felicită-te pentru un lucru care ți-a ieșit azi."}},{"id":24,"t":{"ko":"오늘 처음 해 본 게 있나요?","en":"Did you try anything for the first time today?","ja":"今日、初めてやってみたことはありますか？","zh":"今天有第一次尝试的事吗？","es":"¿Hiciste algo por primera vez hoy?","pt":"Você fez algo pela primeira vez hoje?","th":"วันนี้มีอะไรที่ได้ลองทำเป็นครั้งแรกไหม","ar":"هل جرّبت شيئًا لأول مرة اليوم؟","tr":"Bugün ilk kez yaptığın bir şey oldu mu?","de":"Hast du heute etwas zum ersten Mal gemacht?","fr":"Avez-vous fait quelque chose pour la première fois aujourd’hui ?","nl":"Heb je vandaag iets voor het eerst gedaan?","pl":"Czy coś zdarzyło ci się dziś po raz pierwszy?","ro":"Ai făcut azi ceva pentru prima dată?"}},{"id":25,"t":{"ko":"오늘 들은 말 중에 마음에 남은 한마디는?","en":"What’s one thing you heard today that stuck with you?","ja":"今日聞いた言葉で、心に残ったひと言は？","zh":"今天听到的话里，哪一句留在了心里？","es":"¿Qué te dijeron hoy que se te quedó grabado?","pt":"Que frase você ouviu hoje e guardou no coração?","th":"วันนี้มีคำพูดไหนที่ยังติดอยู่ในใจ","ar":"أيّ كلمة سمعتها اليوم بقيت في قلبك؟","tr":"Bugün duyduğun sözlerden hangisi aklında kaldı?","de":"Welcher Satz von heute klingt in dir nach?","fr":"Quelle parole entendue aujourd’hui vous est restée ?","nl":"Welke woorden van vandaag zijn je bijgebleven?","pl":"Jakie usłyszane dziś słowa zostały ci w sercu?","ro":"Ce vorbă auzită azi ți-a rămas în suflet?"}},{"id":26,"t":{"ko":"오늘의 작은 행운을 적어 봐요.","en":"Write down today’s little stroke of luck.","ja":"今日の小さなラッキーを書いてみましょう。","zh":"写下今天的小幸运吧。","es":"Anota tu pequeño golpe de suerte de hoy.","pt":"Anote a pequena sorte de hoje.","th":"ลองจดเรื่องโชคดีเล็กๆ ของวันนี้ดูนะ","ar":"دوِّن لحظة حظ صغيرة من اليوم.","tr":"Bugünkü küçük şansını yaz.","de":"Schreib deinen kleinen Glücksmoment von heute auf.","fr":"Notez votre petit coup de chance du jour.","nl":"Schrijf je kleine geluksmomentje van vandaag op.","pl":"Zapisz swoje dzisiejsze małe szczęście.","ro":"Notează micul tău noroc de azi."}},{"id":27,"t":{"ko":"오늘 가장 맛있었던 건?","en":"What was the tastiest thing you had today?","ja":"今日いちばんおいしかったものは？","zh":"今天最好吃的是什么？","es":"¿Qué fue lo más rico que comiste hoy?","pt":"Qual foi a coisa mais gostosa de hoje?","th":"วันนี้อะไรอร่อยที่สุด","ar":"ما ألذّ شيء تناولته اليوم؟","tr":"Bugün yediğin en lezzetli şey neydi?","de":"Was war heute am leckersten?","fr":"Qu’avez-vous mangé de meilleur aujourd’hui ?","nl":"Wat was vandaag het lekkerst?","pl":"Co dziś smakowało ci najbardziej?","ro":"Ce ai mâncat cel mai bun azi?"}},{"id":28,"t":{"ko":"오늘 나를 힘들게 한 일, 여기에 내려놓아요.","en":"Whatever weighed on you today, set it down here.","ja":"今日つらかったことは、ここに置いていきましょう。","zh":"今天让你累的事，就放在这里吧。","es":"Lo que hoy te pesó, déjalo aquí.","pt":"O que pesou hoje, deixe aqui.","th":"เรื่องที่ทำให้เหนื่อยใจวันนี้ วางไว้ตรงนี้นะ","ar":"ما أتعبك اليوم، ضعه هنا وارتح.","tr":"Bugün seni yoran şeyi buraya bırak.","de":"Was dich heute belastet hat, darfst du hier ablegen.","fr":"Ce qui a été dur aujourd’hui, déposez-le ici.","nl":"Wat je vandaag zwaar viel, mag je hier neerleggen.","pl":"To, co dziś było ciężkie, możesz tu odłożyć.","ro":"Lasă aici ce te-a apăsat azi."}},{"id":29,"t":{"ko":"오늘 배운 것 하나를 남겨요.","en":"Note one thing you learned today.","ja":"今日学んだことを、ひとつ残しましょう。","zh":"记下今天学到的一件事吧。","es":"Guarda algo que aprendiste hoy.","pt":"Guarde uma coisa que você aprendeu hoje.","th":"เก็บสิ่งที่ได้เรียนรู้วันนี้ไว้สักเรื่อง","ar":"دوِّن شيئًا واحدًا تعلّمته اليوم.","tr":"Bugün öğrendiğin bir şeyi not et.","de":"Halte eine Sache fest, die du heute gelernt hast.","fr":"Notez une chose que vous avez apprise aujourd’hui.","nl":"Leg één ding vast dat je vandaag hebt geleerd.","pl":"Czego nauczył cię dzisiejszy dzień? Zapisz to.","ro":"Notează un lucru pe care l-ai învățat azi."}},{"id":30,"t":{"ko":"오늘 하루에 점수를 준다면 몇 점일까요?","en":"If you gave today a score, what would it be?","ja":"今日に点数をつけるなら、何点ですか？","zh":"给今天打个分，会是几分？","es":"¿Qué nota le pondrías a tu día?","pt":"Se você desse uma nota para o seu dia, qual seria?","th":"ถ้าให้คะแนนวันนี้ จะให้กี่คะแนน","ar":"لو أعطيت يومك درجة، فكم ستكون؟","tr":"Bugüne puan versen kaç verirdin?","de":"Wie viele Punkte gibst du dem heutigen Tag?","fr":"Quelle note donneriez-vous à votre journée ?","nl":"Welk cijfer geef je je dag vandaag?","pl":"Na ile punktów oceniasz dzisiejszy dzień?","ro":"Ce notă i-ai da zilei de azi?"}},{"id":31,"t":{"ko":"오늘 본 하늘은 어떤 색이었나요?","en":"What color was the sky today?","ja":"今日見た空は、どんな色でしたか？","zh":"今天看到的天空是什么颜色？","es":"¿De qué color era el cielo hoy?","pt":"De que cor estava o céu hoje?","th":"ท้องฟ้าที่เห็นวันนี้เป็นสีอะไร","ar":"ما لون السماء التي رأيتها اليوم؟","tr":"Bugün gökyüzü ne renkti?","de":"Welche Farbe hatte der Himmel heute?","fr":"De quelle couleur était le ciel aujourd’hui ?","nl":"Welke kleur had de lucht vandaag?","pl":"Jakiego koloru było dziś niebo?","ro":"Ce culoare a avut cerul azi?"}},{"id":32,"t":{"ko":"오늘 나에게 해 주고 싶은 말은?","en":"What would you like to tell yourself today?","ja":"今日の自分にかけてあげたい言葉は？","zh":"今天想对自己说什么？","es":"¿Qué te gustaría decirte hoy?","pt":"O que você precisa ouvir de você hoje?","th":"วันนี้อยากบอกอะไรกับตัวเอง","ar":"ما الذي تودّ أن تقوله لنفسك اليوم؟","tr":"Bugün kendine ne söylemek isterdin?","de":"Was möchtest du dir heute sagen?","fr":"Que voudriez-vous vous dire aujourd’hui ?","nl":"Wat wil je vandaag tegen jezelf zeggen?","pl":"Co chcesz dziś sobie powiedzieć?","ro":"Ce vrei să-ți spui azi?"}},{"id":33,"t":{"ko":"오늘 미룬 일이 있다면, 내일의 나에게 부탁해요.","en":"Put something off today? Leave it to tomorrow’s you.","ja":"今日やり残したことは、明日の自分にお願いしましょう。","zh":"今天拖延的事，就拜托明天的自己吧。","es":"Si hoy dejaste algo pendiente, encárgaselo a tu yo de mañana.","pt":"Se ficou algo pendente hoje, deixe para o você de amanhã.","th":"ถ้าวันนี้มีเรื่องที่ผัดไว้ ฝากตัวเราในวันพรุ่งนี้ด้วยนะ","ar":"إن أجّلت شيئًا اليوم، فاتركه لنفسك في الغد.","tr":"Bugün ertelediğin bir iş varsa, yarınki sana emanet et.","de":"Etwas aufgeschoben? Übergib es deinem Ich von morgen.","fr":"Vous avez remis quelque chose à plus tard ? Confiez-le à demain.","nl":"Iets uitgesteld? Laat het over aan jezelf van morgen.","pl":"Coś odkładasz? Przekaż to sobie na jutro.","ro":"Ai amânat ceva? Lasă-l pe mâine, în grija ta."}},{"id":34,"t":{"ko":"오늘 가장 오래 생각한 건 무엇이었나요?","en":"What did you think about the most today?","ja":"今日いちばん長く考えていたことは？","zh":"今天想得最久的是什么？","es":"¿En qué pensaste más hoy?","pt":"No que você mais pensou hoje?","th":"วันนี้คิดเรื่องอะไรนานที่สุด","ar":"ما الذي أطلت التفكير فيه اليوم؟","tr":"Bugün en çok ne hakkında düşündün?","de":"Worüber hast du heute am längsten nachgedacht?","fr":"À quoi avez-vous le plus pensé aujourd’hui ?","nl":"Waar heb je vandaag het langst over nagedacht?","pl":"Co dziś najdłużej chodziło ci po głowie?","ro":"La ce te-ai gândit cel mai mult azi?"}},{"id":35,"t":{"ko":"오늘 들은 노래가 있다면 남겨 둬요.","en":"Heard a song today? Save it here.","ja":"今日聴いた曲があれば、残しておきましょう。","zh":"今天听了什么歌？记下来吧。","es":"Si escuchaste una canción hoy, apúntala.","pt":"Se ouviu alguma música hoje, deixe anotada.","th":"วันนี้ได้ฟังเพลงอะไร เก็บไว้ตรงนี้ได้นะ","ar":"إن استمعت إلى أغنية اليوم، فاحفظها هنا.","tr":"Bugün dinlediğin bir şarkı varsa, buraya bırak.","de":"Hast du heute ein Lied gehört? Halte es hier fest.","fr":"Une chanson écoutée aujourd’hui ? Notez-la.","nl":"Vandaag een liedje gehoord? Bewaar het hier.","pl":"Jakaś piosenka dzisiaj? Zapisz ją tutaj.","ro":"Ai ascultat azi o melodie? Păstreaz-o aici."}},{"id":36,"t":{"ko":"오늘 나를 편안하게 한 순간은?","en":"What moment felt most peaceful today?","ja":"今日ほっとした瞬間は？","zh":"今天让你感到放松的瞬间是？","es":"¿Qué momento de hoy te dio paz?","pt":"Qual momento de hoje trouxe paz para você?","th":"วันนี้ช่วงไหนที่รู้สึกสบายใจที่สุด","ar":"ما اللحظة التي أراحتك اليوم؟","tr":"Bugün seni rahatlatan an hangisiydi?","de":"Welcher Moment hat dir heute Ruhe geschenkt?","fr":"Quel moment de la journée vous a fait du bien ?","nl":"Wanneer voelde je je vandaag echt op je gemak?","pl":"Jaka chwila dała ci dziś spokój?","ro":"Ce moment te-a liniștit azi?"}},{"id":37,"t":{"ko":"오늘의 나는 어제의 나와 무엇이 달랐나요?","en":"How was today’s you different from yesterday’s?","ja":"今日の自分は、昨日の自分と何が違いましたか？","zh":"今天的你和昨天的你有什么不同？","es":"¿Qué fue distinto en ti hoy respecto a ayer?","pt":"O que foi diferente em você hoje, comparado a ontem?","th":"ตัวเราวันนี้ต่างจากเมื่อวานยังไงบ้าง","ar":"بماذا اختلفت اليوم عمّا كنت عليه أمس؟","tr":"Bugünkü sen, dünkü senden nasıl farklıydın?","de":"Was war heute an dir anders als gestern?","fr":"Qu’est-ce qui a changé en vous depuis hier ?","nl":"Wat was er vandaag anders aan jou dan gisteren?","pl":"Co dziś było w tobie inne niż wczoraj?","ro":"Ce a fost diferit azi la tine față de ieri?"}},{"id":38,"t":{"ko":"오늘 하루를 사진 한 장으로 남긴다면?","en":"If today were one photo, what would it be?","ja":"今日を写真一枚で残すなら？","zh":"如果用一张照片留住今天，会是哪一张？","es":"Si guardaras el día en una sola foto, ¿cuál sería?","pt":"Se o seu dia fosse uma única foto, qual seria?","th":"ถ้าเก็บวันนี้ไว้ด้วยรูปเดียว จะเป็นรูปอะไร","ar":"لو حفظت يومك في صورة واحدة، فأيّ صورة تختار؟","tr":"Bugünü tek bir fotoğrafla anlatsan?","de":"Wenn dein Tag ein einziges Foto wäre, welches wäre es?","fr":"Si votre journée tenait en une photo, laquelle serait-ce ?","nl":"Als je je dag in één foto moest vangen, welke zou het zijn?","pl":"Gdyby dzisiejszy dzień był jednym zdjęciem, co by na nim było?","ro":"Dacă ziua de azi ar fi o singură poză, ce ar fi în ea?"}},{"id":39,"t":{"ko":"오늘 누군가에게 하지 못한 말을 적어 봐요.","en":"Write what you couldn’t say to someone today.","ja":"今日、誰かに言えなかったことを書いてみましょう。","zh":"写下今天没能对某人说出口的话吧。","es":"Escribe lo que hoy no pudiste decirle a alguien.","pt":"Escreva o que você não conseguiu dizer a alguém hoje.","th":"ลองเขียนคำที่วันนี้อยากบอกใครสักคนแต่ไม่ได้บอก","ar":"اكتب كلامًا لم تستطع قوله لأحد اليوم.","tr":"Bugün birine söyleyemediğin sözü yaz.","de":"Schreib auf, was du heute jemandem nicht sagen konntest.","fr":"Écrivez ce que vous n’avez pas pu dire à quelqu’un aujourd’hui.","nl":"Schrijf op wat je vandaag niet tegen iemand kon zeggen.","pl":"Zapisz to, czego nie udało ci się dziś komuś powiedzieć.","ro":"Scrie ce n-ai reușit să-i spui azi cuiva."}},{"id":40,"t":{"ko":"오늘 가장 나다웠던 순간은?","en":"When did you feel most like yourself today?","ja":"今日いちばん自分らしかった瞬間は？","zh":"今天最像自己的瞬间是？","es":"¿Cuándo fuiste más tú hoy?","pt":"Quando você foi mais você hoje?","th":"วันนี้ช่วงไหนที่เป็นตัวเองที่สุด","ar":"متى كنت أقرب إلى نفسك اليوم؟","tr":"Bugün en çok kendin olduğun an hangisiydi?","de":"Wann warst du heute am meisten du selbst?","fr":"Quand avez-vous été le plus vous-même aujourd’hui ?","nl":"Wanneer was je vandaag het meest jezelf?","pl":"Jaka chwila była dziś najbardziej twoja?","ro":"Când ai fost azi cel mai mult tu?"}},{"id":41,"t":{"ko":"힘든 날일수록 한 줄이 위로가 돼요.","en":"On hard days, one line can be a comfort.","ja":"つらい日ほど、一行が支えになります。","zh":"越是难熬的日子，一行字越能给人安慰。","es":"En los días difíciles, una línea puede ser un consuelo.","pt":"Nos dias difíceis, uma linha já é um consolo.","th":"ยิ่งเป็นวันที่เหนื่อย หนึ่งบรรทัดยิ่งช่วยปลอบใจ","ar":"في الأيام الصعبة، يصبح السطر الواحد عزاءً.","tr":"Zor günlerde bir satır bile teselli olur.","de":"Gerade an schweren Tagen tröstet eine Zeile.","fr":"Les jours difficiles, une ligne peut réconforter.","nl":"Juist op zware dagen troost één regel.","pl":"W trudne dni jedna linijka potrafi pocieszyć.","ro":"În zilele grele, un rând poate alina."}},{"id":42,"t":{"ko":"오늘의 마음을 꺼내 놓으면 조금 가벼워져요.","en":"Let today’s feelings out, and you’ll feel a bit lighter.","ja":"今日の気持ちを書き出すと、少し軽くなります。","zh":"把今天的心情写出来，会轻松一点。","es":"Sacar lo que sientes te aligera un poco.","pt":"Colocar o que sente para fora deixa tudo um pouco mais leve.","th":"ได้ระบายความรู้สึกออกมา ใจจะเบาลงนิดนึง","ar":"حين تُخرج ما في قلبك، تشعر بخفّة أكبر.","tr":"İçini döktükçe biraz hafiflersin.","de":"Wenn du rauslässt, was dich bewegt, wird es ein bisschen leichter.","fr":"Mettre des mots sur ce qu’on ressent, ça allège un peu.","nl":"Als je je gevoel even kwijt kunt, wordt het wat lichter.","pl":"Gdy wyrzucisz z siebie emocje, robi się trochę lżej.","ro":"Când îți descarci sufletul, îți e puțin mai ușor."}},{"id":43,"t":{"ko":"아무에게도 못 한 이야기, 여기엔 해도 괜찮아요.","en":"What you couldn’t tell anyone, you can tell here.","ja":"誰にも言えなかった話も、ここなら大丈夫。","zh":"对谁都没说的话，在这里说也没关系。","es":"Lo que no le has contado a nadie, aquí puedes contarlo.","pt":"O que você não contou a ninguém, aqui pode contar.","th":"เรื่องที่เล่าให้ใครฟังไม่ได้ เล่าตรงนี้ได้นะ","ar":"ما لم تستطع قوله لأحد، يمكنك قوله هنا.","tr":"Kimseye anlatamadığını burada anlatabilirsin.","de":"Was du niemandem erzählt hast, darf hier stehen.","fr":"Ce que vous n’avez dit à personne, vous pouvez l’écrire ici.","nl":"Wat je aan niemand kunt vertellen, mag je hier kwijt.","pl":"To, czego nie mówisz nikomu, możesz powiedzieć tutaj.","ro":"Ce n-ai putut spune nimănui, poți spune aici."}},{"id":44,"t":{"ko":"지친 하루였다면 '고생했다' 한 줄도 좋아요.","en":"Rough day? Even just “You did well today” is enough.","ja":"疲れた日は「おつかれさま」の一行だけでも。","zh":"累了一天的话，写一句“辛苦了”也很好。","es":"Si fue un día agotador, basta con un «Hoy di lo mejor de mí».","pt":"Se o dia foi puxado, basta um “Hoje eu dei o meu melhor”.","th":"ถ้าวันนี้เหนื่อยมาก แค่เขียนว่า “วันนี้เก่งมากแล้ว” ก็พอ","ar":"إن كان يومك مُتعبًا، فيكفي سطر: «لقد بذلتُ جهدي».","tr":"Yorucu bir gündüyse “Aferin bana” yazman bile yeter.","de":"Anstrengender Tag? Ein „Gut gemacht“ reicht auch.","fr":"Journée épuisante ? Un simple « J’ai fait de mon mieux » suffit.","nl":"Zware dag gehad? Gewoon ‘goed gedaan’ opschrijven is ook prima.","pl":"Męczący dzień? Wystarczy jedno „dobra robota”.","ro":"Zi obositoare? Ajunge și un simplu „Bravo mie”."}},{"id":45,"t":{"ko":"울적한 날도 소중한 한 칸이에요.","en":"Even a gloomy day is a precious box.","ja":"落ち込んだ日も、大切なひとマスです。","zh":"低落的日子，也是珍贵的一格。","es":"Un día triste también es una casilla valiosa.","pt":"Um dia triste também é um quadrinho precioso.","th":"วันที่เศร้าก็เป็นช่องที่มีค่าเหมือนกัน","ar":"حتى الأيام الحزينة خانات ثمينة.","tr":"Hüzünlü bir gün de değerli bir kutudur.","de":"Auch ein trüber Tag ist ein wertvolles Feld.","fr":"Un jour de blues, c’est aussi une case précieuse.","nl":"Ook een sombere dag is een waardevol vakje.","pl":"Smutny dzień to też cenna kratka.","ro":"Și o zi tristă e o căsuță prețioasă."}},{"id":46,"t":{"ko":"기분이 좋지 않아도 괜찮아요. 그대로 적어 봐요.","en":"It’s okay not to feel great. Write it down as it is.","ja":"気分がよくなくても大丈夫。そのまま書いてみましょう。","zh":"心情不好也没关系，照实写下来吧。","es":"Está bien no estar bien. Escríbelo tal cual.","pt":"Tudo bem não estar bem. Escreva do jeito que for.","th":"อารมณ์ไม่ดีก็ไม่เป็นไร เขียนออกมาตามจริงเลย","ar":"لا بأس إن لم يكن مزاجك جيدًا. اكتبه كما هو.","tr":"Keyfin yerinde olmasa da olur. Olduğu gibi yaz.","de":"Schlechte Laune ist okay. Schreib sie einfach auf.","fr":"Pas le moral ? Ce n’est pas grave. Écrivez-le tel quel.","nl":"Voel je je niet goed? Dat mag. Schrijf het gewoon op.","pl":"Gorszy humor? Nic nie szkodzi. Po prostu go zapisz.","ro":"E în regulă să nu fii bine. Scrie așa cum e."}},{"id":47,"t":{"ko":"오늘도 잘 버텼어요. 그 하루를 남겨 둬요.","en":"You made it through today. Write that down.","ja":"今日もよく乗り切りましたね。その一日を残しましょう。","zh":"今天也撑过来了，把它记下来吧。","es":"Hoy también aguantaste. Déjalo escrito.","pt":"Você aguentou mais um dia. Registre isso.","th":"วันนี้ก็อดทนผ่านมาได้อีกวัน จดเรื่องนี้ไว้นะ","ar":"لقد صمدت اليوم أيضًا. دوِّن ذلك.","tr":"Bugünü de atlattın. Bunu kaydet.","de":"Du hast auch heute durchgehalten. Halte das fest.","fr":"Aujourd’hui encore, vous avez tenu bon. Gardez-en une trace.","nl":"Je hebt het vandaag weer volgehouden. Leg dat vast.","pl":"Dziś znowu dajesz radę. Zapisz to.","ro":"Ai rezistat și azi. Notează asta."}},{"id":48,"t":{"ko":"내 마음을 가장 잘 들어 줄 사람은 나예요.","en":"No one listens to your heart better than you.","ja":"自分の気持ちをいちばん聞いてあげられるのは、自分です。","zh":"最懂得倾听你内心的人，是你自己。","es":"Quien mejor te escucha eres tú.","pt":"Quem melhor escuta o seu coração é você.","th":"คนที่ฟังใจเราได้ดีที่สุด คือตัวเราเอง","ar":"أفضل من يُصغي إلى قلبك هو أنت.","tr":"Seni en iyi dinleyecek kişi yine sensin.","de":"Niemand hört dir besser zu als du selbst.","fr":"La personne qui vous écoute le mieux, c’est vous.","nl":"Niemand luistert beter naar je dan jijzelf.","pl":"Nikt nie wysłucha cię lepiej niż ty.","ro":"Nimeni nu te ascultă mai bine decât tine."}},{"id":49,"t":{"ko":"걱정은 적어 두면 작아져요.","en":"Worries shrink once you write them down.","ja":"心配ごとは、書き出すと小さくなります。","zh":"担心的事，写下来就会变小。","es":"Las preocupaciones se encogen al escribirlas.","pt":"As preocupações diminuem quando você as escreve.","th":"ความกังวลจะเล็กลงเมื่อได้เขียนออกมา","ar":"القلق يصغر حين تكتبه.","tr":"Endişeler yazıya dökülünce küçülür.","de":"Aufgeschriebene Sorgen werden kleiner.","fr":"Une inquiétude, une fois écrite, paraît plus petite.","nl":"Zorgen worden kleiner als je ze opschrijft.","pl":"Zapisane zmartwienia stają się mniejsze.","ro":"Grijile scrise devin mai mici."}},{"id":50,"t":{"ko":"화났던 일도 적고 나면 마음이 한결 차분해져요.","en":"Even anger cools once you write it down.","ja":"腹が立ったことも、書けば気持ちが落ち着きます。","zh":"生气的事写下来，心情也会平静许多。","es":"Hasta el enfado se calma después de escribirlo.","pt":"Até a raiva se acalma depois que você escreve.","th":"แม้แต่เรื่องที่ทำให้โกรธ เขียนออกมาแล้วใจจะสงบขึ้น","ar":"حتى ما أغضبك اليوم، ستهدأ بعد أن تكتبه.","tr":"Seni kızdıran şeyi bile yazınca biraz sakinleşirsin.","de":"Auch Ärger legt sich, wenn du ihn aufschreibst.","fr":"Même la colère s’apaise une fois écrite.","nl":"Ook boosheid zakt als je die opschrijft.","pl":"Nawet złość cichnie, gdy ją zapiszesz.","ro":"Și furia se domolește după ce o scrii."}},{"id":51,"t":{"ko":"좋은 날은 오래 기억하려고, 힘든 날은 흘려보내려고 써요.","en":"Write to remember the good days and let the hard ones go.","ja":"いい日は長く覚えておくために、つらい日は手放すために書きます。","zh":"写下来，是为了记住美好的日子，放下难熬的日子。","es":"Escribe para recordar los días buenos y dejar ir los difíciles.","pt":"Escreva para lembrar os dias bons e deixar os difíceis para trás.","th":"เขียนเพื่อจำวันดีๆ ไว้นานๆ และปล่อยวันที่เหนื่อยให้ผ่านไป","ar":"نكتب لنتذكّر الأيام الجميلة طويلًا، ولندع الأيام الصعبة تمضي.","tr":"İyi günleri uzun süre hatırlamak, zor günleri geride bırakmak için yaz.","de":"Gute Tage schreibst du zum Erinnern, schwere zum Loslassen.","fr":"On écrit pour garder les beaux jours et laisser filer les jours difficiles.","nl":"Goede dagen schrijf je op om te onthouden, zware om los te laten.","pl":"Dobre dni zapisujesz, by je zapamiętać, a trudne, by je odpuścić.","ro":"Scrii zilele bune ca să le ții minte, iar pe cele grele ca să treacă."}},{"id":52,"t":{"ko":"오늘을 잘 보내지 못했어도, 남기는 건 잘한 일이에요.","en":"Even if today didn’t go well, writing it down was the right call.","ja":"うまくいかなかった日でも、書き残せた自分はえらい。","zh":"即使今天过得不太好，记录下来也是件好事。","es":"Aunque hoy no haya salido bien, escribirlo sí fue un acierto.","pt":"Mesmo que o dia não tenha sido bom, registrá-lo foi uma boa escolha.","th":"แม้วันนี้จะผ่านไปไม่ค่อยดี แต่การได้บันทึกไว้ก็ถือว่าทำดีแล้ว","ar":"حتى لو لم يكن يومك جيدًا، فتدوينه خطوة تُحسب لك.","tr":"Bugün iyi geçmediyse bile, onu kaydetmen iyi bir şey.","de":"Lief der Tag nicht gut? Ihn festzuhalten, ist trotzdem richtig.","fr":"Même si la journée n’a pas été bonne, l’écrire, c’est déjà bien.","nl":"Ging het vandaag niet goed? Toch goed dat je het opschrijft.","pl":"Nawet jeśli dzień nie wyszedł, dobrze, że go zapisujesz.","ro":"Chiar dacă ziua n-a ieșit cum voiai, e bine că o notezi."}},{"id":53,"t":{"ko":"오늘 써 두면 내일의 내가 고마워할 거예요.","en":"Tomorrow’s you will thank today’s you for writing.","ja":"明日の自分は、今日書いた自分にきっと感謝します。","zh":"明天的你，会感谢今天写下这些的自己。","es":"Tu yo de mañana te agradecerá haber escrito hoy.","pt":"O você de amanhã vai agradecer por ter escrito hoje.","th":"ตัวเราในวันพรุ่งนี้จะขอบคุณที่วันนี้เราเขียนไว้","ar":"ستشكرك نفسك في الغد لأنك كتبت اليوم.","tr":"Yarınki sen, bugün yazdığın için sana teşekkür edecek.","de":"Dein Ich von morgen wird dir fürs Schreiben danken.","fr":"Demain, vous vous remercierez d’avoir écrit aujourd’hui.","nl":"Morgen ben je jezelf dankbaar dat je vandaag schreef.","pl":"Jutro podziękujesz sobie za dzisiejszy wpis.","ro":"Mâine îți vei mulțumi că ai scris azi."}},{"id":54,"t":{"ko":"마음이 복잡할 땐 떠오르는 단어부터 적어 봐요.","en":"When your mind feels tangled, start with whatever word comes first.","ja":"気持ちがまとまらない時は、浮かんだ言葉から書いてみましょう。","zh":"心里乱的时候，就从脑海里浮现的词开始写吧。","es":"Cuando tengas la cabeza revuelta, empieza por la palabra que te venga.","pt":"Quando a cabeça estiver confusa, comece pela palavra que vier.","th":"เวลาใจสับสน ลองเริ่มเขียนจากคำที่นึกขึ้นได้ก่อน","ar":"حين تتزاحم مشاعرك، ابدأ بأول كلمة تخطر لك.","tr":"Kafan karışıkken aklına gelen ilk kelimeyle başla.","de":"Alles durcheinander? Schreib erst mal die Wörter auf, die dir einfallen.","fr":"Quand tout s’embrouille, commencez par le premier mot qui vient.","nl":"Hoofd vol? Begin met de woorden die opkomen.","pl":"Mętlik w głowie? Zapisz pierwsze słowa, które się pojawią.","ro":"Gânduri încâlcite? Începe cu primele cuvinte care-ți vin."}},{"id":55,"t":{"ko":"오늘 나에게 가장 다정했던 사람은 누구였나요?","en":"Who was kindest to you today?","ja":"今日、いちばんやさしくしてくれたのは誰でしたか？","zh":"今天对你最温柔的人是谁？","es":"¿Quién fue la persona más amable contigo hoy?","pt":"Quem foi mais gentil com você hoje?","th":"วันนี้ใครใจดีกับเรามากที่สุด","ar":"من كان ألطف شخص معك اليوم؟","tr":"Bugün sana en nazik davranan kimdi?","de":"Wer war heute besonders lieb zu dir?","fr":"Qui a été le plus gentil avec vous aujourd’hui ?","nl":"Wie was vandaag het aardigst voor je?","pl":"Kto był dziś dla ciebie najmilszy?","ro":"Cine a fost azi cel mai drăguț cu tine?"}},{"id":56,"t":{"ko":"한 칸 한 칸이 모여 나의 한 해가 돼요.","en":"Box by box, your year takes shape.","ja":"ひとマスひとマスが集まって、あなたの一年になります。","zh":"一格一格，汇成你的一年。","es":"Casilla a casilla, se forma tu año.","pt":"Um quadrinho de cada vez, seu ano vai se formando.","th":"ทีละช่อง ทีละช่อง รวมกันเป็นหนึ่งปีของเรา","ar":"خانةً بعد خانة، تتكوّن سنتك.","tr":"Kutu kutu biriken günler senin yılın olur.","de":"Feld für Feld wird daraus dein Jahr.","fr":"Case après case, votre année prend forme.","nl":"Vakje voor vakje wordt het jouw jaar.","pl":"Kratka po kratce układa się twój rok.","ro":"Căsuță cu căsuță, se adună anul tău."}},{"id":57,"t":{"ko":"평범한 오늘이 1년 뒤엔 그리운 추억이 돼요.","en":"Today’s ordinary moments become next year’s fond memories.","ja":"何気ない今日が、1年後には懐かしい思い出に。","zh":"今天的平凡，一年后会成为令人怀念的回忆。","es":"Lo cotidiano de hoy será un recuerdo querido dentro de un año.","pt":"A rotina de hoje vira uma lembrança querida daqui a um ano.","th":"วันธรรมดาๆ วันนี้ อีกหนึ่งปีจะกลายเป็นความทรงจำที่คิดถึง","ar":"يومك العادي سيصبح بعد عام ذكرى تشتاق إليها.","tr":"Bugünün sıradanlığı bir yıl sonra özlenen bir anı olur.","de":"Der Alltag von heute ist in einem Jahr eine schöne Erinnerung.","fr":"L’ordinaire d’aujourd’hui sera un doux souvenir dans un an.","nl":"Het gewone van vandaag is over een jaar een dierbare herinnering.","pl":"Dzisiejsza zwyczajność za rok będzie miłym wspomnieniem.","ro":"Banalul de azi devine peste un an o amintire dragă."}},{"id":58,"t":{"ko":"1년 뒤 오늘, 이 한 칸을 다시 보게 될 거예요.","en":"A year from today, you’ll see this box again.","ja":"1年後の今日、このマスをまた見返すはず。","zh":"一年后的今天，你会再看到这一格。","es":"Dentro de un año volverás a ver esta casilla.","pt":"Daqui a um ano, você vai rever este quadrinho.","th":"อีกหนึ่งปีจากวันนี้ เราจะได้กลับมาเห็นช่องนี้อีกครั้ง","ar":"بعد عام من اليوم، سترى هذه الخانة من جديد.","tr":"Bir yıl sonra bugün, bu kutuya yeniden bakacaksın.","de":"Heute in einem Jahr siehst du dieses Feld wieder.","fr":"Dans un an jour pour jour, vous relirez cette case.","nl":"Vandaag over een jaar zie je dit vakje terug.","pl":"Za rok, tego samego dnia, znów zobaczysz tę kratkę.","ro":"Peste un an, în aceeași zi, vei revedea căsuța asta."}},{"id":59,"t":{"ko":"사소한 기록이 가장 소중한 기록이 돼요.","en":"Little notes become the most precious ones.","ja":"ささいな記録こそ、いちばん大切な記録になります。","zh":"微不足道的记录，会成为最珍贵的记录。","es":"Los apuntes más pequeños se vuelven los más valiosos.","pt":"Os registros pequenos viram os mais preciosos.","th":"บันทึกเล็กๆ จะกลายเป็นบันทึกที่มีค่าที่สุด","ar":"أبسط التدوينات تصبح أثمنها.","tr":"En küçük kayıtlar en değerli kayıtlar olur.","de":"Die kleinsten Notizen werden die wertvollsten.","fr":"Les petites notes deviennent les plus précieuses.","nl":"Kleine notities worden de waardevolste.","pl":"Drobne zapiski stają się najcenniejsze.","ro":"Notițele mărunte devin cele mai prețioase."}},{"id":60,"t":{"ko":"기억은 흐려져도 기록은 남아요.","en":"Memories fade, but records remain.","ja":"記憶は薄れても、記録は残ります。","zh":"记忆会模糊，但记录会留下。","es":"Los recuerdos se desvanecen; lo escrito permanece.","pt":"A memória se apaga, mas o registro fica.","th":"ความทรงจำอาจเลือนลาง แต่บันทึกยังคงอยู่","ar":"الذكريات تبهت، لكن ما يُكتب يبقى.","tr":"Anılar solar, kayıtlar kalır.","de":"Erinnerungen verblassen, Aufgeschriebenes bleibt.","fr":"La mémoire s’efface, l’écrit reste.","nl":"Herinneringen vervagen, wat je opschrijft blijft.","pl":"Wspomnienia blakną, zapiski zostają.","ro":"Amintirile pălesc, ce scrii rămâne."}},{"id":61,"t":{"ko":"쌓인 칸들이 나에 대해 말해 줄 거예요.","en":"Your boxes will tell your story.","ja":"積み重なったマスが、あなたのことを語ってくれます。","zh":"积累起来的格子，会讲述你的故事。","es":"Tus casillas acumuladas hablarán de ti.","pt":"Seus quadrinhos vão contar quem você é.","th":"ช่องที่สะสมไว้จะเล่าเรื่องของเราให้ฟัง","ar":"الخانات المتراكمة ستحكي عنك.","tr":"Biriken kutular sana kendini anlatacak.","de":"Deine Felder werden viel über dich erzählen.","fr":"Vos cases parleront de vous.","nl":"Al je vakjes samen vertellen wie je bent.","pl":"Twoje kratki opowiedzą o tobie.","ro":"Căsuțele adunate vor povesti despre tine."}},{"id":62,"t":{"ko":"오늘을 적다 보면 오늘을 한 번 더 만나게 돼요.","en":"Write about today, and you live it once more.","ja":"今日を書くと、もう一度今日に出会えます。","zh":"写下今天，就等于把今天再过一次。","es":"Escribir tu día es vivirlo una vez más.","pt":"Escrever o dia é vivê-lo mais uma vez.","th":"เมื่อเขียนถึงวันนี้ ก็เหมือนได้ใช้ชีวิตวันนี้อีกครั้ง","ar":"حين تكتب يومك، تعيشه مرة أخرى.","tr":"Bugünü yazınca, bugünü bir kez daha yaşarsın.","de":"Wenn du den Tag aufschreibst, erlebst du ihn ein zweites Mal.","fr":"Écrire sa journée, c’est la vivre une deuxième fois.","nl":"Schrijf je je dag op, dan beleef je hem nog een keer.","pl":"Gdy zapisujesz dzień, przeżywasz go jeszcze raz.","ro":"Când scrii ziua de azi, o trăiești încă o dată."}},{"id":63,"t":{"ko":"하루 한 칸, 나를 알아 가는 가장 쉬운 방법이에요.","en":"One box a day: the easiest way to know yourself.","ja":"1日1マス、自分を知るいちばん簡単な方法です。","zh":"一天一格，是认识自己最简单的方法。","es":"Una casilla al día: la forma más fácil de conocerte.","pt":"Um quadrinho por dia: o jeito mais fácil de se conhecer.","th":"วันละช่อง วิธีที่ง่ายที่สุดในการรู้จักตัวเอง","ar":"خانة واحدة كل يوم، أسهل طريقة لتعرف نفسك.","tr":"Günde bir kutu, kendini tanımanın en kolay yolu.","de":"Ein Feld am Tag: der einfachste Weg, dich selbst kennenzulernen.","fr":"Une case par jour : la façon la plus simple de mieux se connaître.","nl":"Eén vakje per dag: de makkelijkste manier om jezelf te leren kennen.","pl":"Jedna kratka dziennie to najprostszy sposób, by poznać siebie.","ro":"O căsuță pe zi: cel mai simplu mod de a te cunoaște."}},{"id":64,"t":{"ko":"어제보다 한 칸 더, 그거면 충분해요.","en":"One more box than yesterday. That’s enough.","ja":"昨日よりひとマス多く。それで十分。","zh":"比昨天多一格，就足够了。","es":"Una casilla más que ayer. Con eso basta.","pt":"Um quadrinho a mais que ontem já basta.","th":"มากกว่าเมื่อวานอีกหนึ่งช่อง แค่นั้นก็พอ","ar":"خانة واحدة أكثر من الأمس، وهذا يكفي.","tr":"Dünden bir kutu fazla, o kadar yeter.","de":"Ein Feld mehr als gestern, das reicht.","fr":"Une case de plus qu’hier, c’est déjà très bien.","nl":"Eén vakje meer dan gisteren, dat is genoeg.","pl":"O jedną kratkę więcej niż wczoraj. To wystarczy.","ro":"O căsuță în plus față de ieri, și e de ajuns."}},{"id":65,"t":{"ko":"연속 기록이 끊겨도 괜찮아요. 오늘부터 다시 한 칸.","en":"Streak broken? That’s okay. Start again today with one box.","ja":"連続記録が途切れても大丈夫。今日からまたひとマス。","zh":"连续记录中断了也没关系，从今天起再填一格。","es":"No pasa nada si se rompe tu racha. Hoy empiezas de nuevo con una casilla.","pt":"Tudo bem se a sequência quebrar. Recomece hoje com um quadrinho.","th":"สถิติต่อเนื่องขาดไปก็ไม่เป็นไร เริ่มช่องใหม่ได้ตั้งแต่วันนี้","ar":"لا بأس إن انقطعت سلسلتك. ابدأ من جديد بخانة اليوم.","tr":"Seri bozulsa da olur. Bugün yeniden bir kutuyla başla.","de":"Serie gerissen? Kein Problem. Ab heute wieder ein Feld.","fr":"Série interrompue ? Pas grave. Recommencez dès aujourd’hui, une case à la fois.","nl":"Reeks onderbroken? Geeft niks. Vandaag gewoon weer een vakje.","pl":"Seria przerwana? Nic nie szkodzi. Zacznij znów od dzisiejszej kratki.","ro":"S-a rupt seria? Nu-i nimic. Reia de azi, cu o căsuță."}},{"id":66,"t":{"ko":"지금 쓰는 한 줄은 미래의 나에게 보내는 편지예요.","en":"The line you write now is a letter to your future self.","ja":"今書いている一行は、未来の自分への手紙です。","zh":"现在写下的一行，是寄给未来自己的信。","es":"Esta línea es una carta a tu yo del futuro.","pt":"Esta linha é uma carta para o você do futuro.","th":"บรรทัดที่เขียนตอนนี้ คือจดหมายถึงตัวเราในอนาคต","ar":"السطر الذي تكتبه الآن رسالة إلى نفسك في المستقبل.","tr":"Şimdi yazdığın satır, gelecekteki sana bir mektup.","de":"Deine Zeile heute ist ein Brief an dein zukünftiges Ich.","fr":"Cette ligne est une lettre à la personne que vous serez.","nl":"Deze regel is een brief aan je toekomstige zelf.","pl":"Ta linijka to list do siebie w przyszłości.","ro":"Rândul de acum e o scrisoare pentru tine din viitor."}},{"id":67,"t":{"ko":"매일 쓰지 않아도 돼요. 쓰고 싶은 날 쓰면 돼요.","en":"No need to write every day. Write when you feel like it.","ja":"毎日書かなくても大丈夫。書きたい日に書けばいいんです。","zh":"不用每天都写，想写的时候写就好。","es":"No hace falta escribir a diario. Escribe cuando te apetezca.","pt":"Não precisa escrever todo dia. Escreva quando tiver vontade.","th":"ไม่ต้องเขียนทุกวันก็ได้ อยากเขียนวันไหนก็เขียนวันนั้น","ar":"لا يلزمك أن تكتب كل يوم. اكتب حين تشاء.","tr":"Her gün yazmak zorunda değilsin. İstediğin gün yaz.","de":"Du musst nicht jeden Tag schreiben. Schreib, wann du magst.","fr":"Pas besoin d’écrire tous les jours. Écrivez quand vous en avez envie.","nl":"Je hoeft niet elke dag te schrijven. Schrijf als je zin hebt.","pl":"Nie musisz pisać codziennie. Pisz, kiedy masz ochotę.","ro":"Nu trebuie să scrii zilnic. Scrie când ai chef."}},{"id":68,"t":{"ko":"오늘의 칸이 비어 있어요. 채워 줄래요?","en":"Today’s box is empty. Want to fill it?","ja":"今日のマスが空いています。埋めてみませんか？","zh":"今天的格子还空着，要填一下吗？","es":"La casilla de hoy está vacía. ¿La llenas?","pt":"O quadrinho de hoje está vazio. Vamos preenchê-lo?","th":"ช่องของวันนี้ยังว่างอยู่ มาเติมกันไหม","ar":"خانة اليوم فارغة. هل تملؤها؟","tr":"Bugünün kutusu boş. Doldurmak ister misin?","de":"Dein Feld heute ist noch leer. Magst du es füllen?","fr":"La case du jour est vide. Vous la remplissez ?","nl":"Het vakje van vandaag is nog leeg. Vul je het?","pl":"Dzisiejsza kratka jest pusta. Wypełnisz ją?","ro":"Căsuța de azi e goală. O completezi?"}},{"id":69,"t":{"ko":"작은 기록이 모이면 나만의 책이 돼요.","en":"Small notes add up to a book of your own.","ja":"小さな記録が集まると、自分だけの本になります。","zh":"小小的记录积累起来，就是一本属于自己的书。","es":"Los pequeños apuntes se convierten en tu propio libro.","pt":"Pequenos registros viram um livro só seu.","th":"บันทึกเล็กๆ ที่รวมกัน จะกลายเป็นหนังสือของเราเอง","ar":"التدوينات الصغيرة حين تجتمع تصبح كتابك الخاص.","tr":"Küçük kayıtlar birikince sana ait bir kitap olur.","de":"Aus kleinen Notizen wird dein ganz eigenes Buch.","fr":"Les petites notes finissent par former votre propre livre.","nl":"Kleine notities samen worden je eigen boek.","pl":"Z małych zapisków powstaje twoja własna książka.","ro":"Notițele mici, adunate, devin propria ta carte."}},{"id":70,"t":{"ko":"오늘의 기분 색이 달력에 하나 더해져요.","en":"Today’s mood adds one more color to your calendar.","ja":"今日の気分の色が、カレンダーにひとつ加わります。","zh":"今天的心情颜色，又为日历添了一笔。","es":"El color de tu ánimo de hoy se suma al calendario.","pt":"A cor do seu humor de hoje entra no calendário.","th":"สีอารมณ์ของวันนี้จะเพิ่มลงในปฏิทินอีกหนึ่งสี","ar":"لون مزاجك اليوم يُضاف إلى التقويم.","tr":"Bugünkü ruh halinin rengi takvime eklenir.","de":"Heute kommt eine neue Stimmungsfarbe in deinen Kalender.","fr":"La couleur de votre humeur du jour s’ajoute au calendrier.","nl":"Vandaag komt de kleur van je stemming erbij in je kalender.","pl":"Dziś w kalendarzu pojawi się kolor twojego nastroju.","ro":"Culoarea stării tale de azi se adaugă în calendar."}},{"id":71,"t":{"ko":"오늘은 남은 날 중 가장 젊은 날이에요.","en":"You’ll never be younger than you are today.","ja":"今日は、残りの人生でいちばん若い日です。","zh":"今天，是余生中最年轻的一天。","es":"De todos los días que te quedan, hoy es el más joven.","pt":"Você nunca vai ser tão jovem quanto hoje.","th":"วันนี้คือวันที่เราอายุน้อยที่สุดในบรรดาวันที่เหลืออยู่","ar":"أنت اليوم أصغر سنًّا من أي يوم قادم.","tr":"Bugün, kalan ömrünün en genç günü.","de":"Von allen Tagen, die noch kommen, bist du heute am jüngsten.","fr":"Aujourd’hui est le plus jeune des jours qu’il vous reste.","nl":"Van alle dagen die nog komen, ben je vandaag het jongst.","pl":"Dziś to najmłodszy dzień z całej reszty twojego życia.","ro":"Azi e cea mai tânără zi din tot restul vieții tale."}},{"id":72,"t":{"ko":"나중에 웃으며 읽을 오늘을 남겨 둬요.","en":"Save today to read later with a smile.","ja":"あとで笑って読める今日を、残しておきましょう。","zh":"把今天记下来，以后笑着再读。","es":"Guarda el hoy que algún día leerás con una sonrisa.","pt":"Guarde o hoje que um dia você vai ler sorrindo.","th":"เก็บวันนี้ไว้ ให้วันหลังได้อ่านแล้วยิ้ม","ar":"احفظ يومًا ستقرؤه لاحقًا وأنت تبتسم.","tr":"İleride gülümseyerek okuyacağın bugünü kaydet.","de":"Halte einen Tag fest, über den du später lächeln wirst.","fr":"Écrivez aujourd’hui ce que vous relirez plus tard en souriant.","nl":"Bewaar een dag waar je later om kunt glimlachen.","pl":"Zapisz dzień, który kiedyś przeczytasz z uśmiechem.","ro":"Păstrează o zi pe care o vei reciti zâmbind."}},{"id":73,"t":{"ko":"오늘의 고민도 1년 뒤엔 별일 아닐 거예요.","en":"A year from now, today’s worries will be no big deal.","ja":"今日の悩みも、1年後にはきっと小さなことに。","zh":"今天的烦恼，一年后也会变得不值一提。","es":"Lo que hoy te preocupa, en un año no será nada.","pt":"A preocupação de hoje, daqui a um ano, não vai ser nada.","th":"เรื่องกลุ้มใจวันนี้ อีกหนึ่งปีอาจกลายเป็นเรื่องเล็กไปแล้ว","ar":"همّ اليوم سيبدو أمرًا بسيطًا بعد عام.","tr":"Bugünkü dertlerin bir yıl sonra önemsiz görünecek.","de":"Die Sorgen von heute sind in einem Jahr wohl nur noch Kleinigkeiten.","fr":"Le souci d’aujourd’hui ne sera plus grand-chose dans un an.","nl":"De zorgen van vandaag zijn over een jaar waarschijnlijk niks meer.","pl":"Dzisiejsze zmartwienia za rok będą pewnie drobiazgiem.","ro":"Grijile de azi, peste un an, probabil nu vor mai conta."}},{"id":74,"t":{"ko":"사진 속엔 없는 오늘의 이야기를 남겨요.","en":"Write the part of today that photos can’t capture.","ja":"写真には写らない今日の話を残しましょう。","zh":"记下照片里没有的、今天的故事。","es":"Guarda la historia de hoy que no sale en las fotos.","pt":"Guarde a história de hoje que não aparece nas fotos.","th":"เก็บเรื่องราวของวันนี้ที่รูปถ่ายเล่าไม่ได้","ar":"دوِّن حكاية اليوم التي لا تظهر في الصور.","tr":"Fotoğraflarda olmayan bugünün hikâyesini yaz.","de":"Schreib die Geschichte auf, die auf keinem Foto ist.","fr":"Écrivez ce que les photos du jour ne racontent pas.","nl":"Schrijf het verhaal op dat niet op de foto staat.","pl":"Zapisz historię, której nie widać na zdjęciach.","ro":"Scrie povestea care nu se vede în poze."}},{"id":75,"t":{"ko":"하루를 기록하는 사람은 하루를 두 번 살아요.","en":"Those who record their days live them twice.","ja":"一日を記録する人は、一日を二度生きる。","zh":"记录生活的人，把每一天都活了两次。","es":"Quien escribe su día lo vive dos veces.","pt":"Quem registra o dia vive o dia duas vezes.","th":"คนที่บันทึกวันของตัวเอง ได้ใช้ชีวิตวันนั้นถึงสองครั้ง","ar":"من يدوّن يومه يعيشه مرتين.","tr":"Gününü yazan, o günü iki kez yaşar.","de":"Wer seinen Tag aufschreibt, lebt ihn zweimal.","fr":"Qui écrit sa journée la vit deux fois.","nl":"Wie zijn dag opschrijft, leeft hem twee keer.","pl":"Kto zapisuje swój dzień, przeżywa go dwa razy.","ro":"Cine își scrie ziua o trăiește de două ori."}},{"id":76,"t":{"ko":"천 리 길도 한 걸음부터 시작된다.","en":"A journey of a thousand miles begins with a single step.","ja":"千里の道も一歩から。","zh":"千里之行，始于足下。","es":"Un viaje de mil millas comienza con un solo paso.","pt":"Uma jornada de mil milhas começa com um único passo.","th":"การเดินทางพันลี้ เริ่มต้นด้วยก้าวแรก","ar":"رحلة الألف ميل تبدأ بخطوة واحدة.","tr":"Bin millik bir yolculuk tek bir adımla başlar.","de":"Auch der längste Weg beginnt mit dem ersten Schritt.","fr":"Un voyage de mille lieues commence par un premier pas.","nl":"Een reis van duizend mijl begint met één enkele stap.","pl":"Podróż tysiąca mil zaczyna się od pierwszego kroku.","ro":"Drumul de o mie de mile începe cu un singur pas."},"by":{"ko":"노자, 『도덕경』","en":"Laozi, Tao Te Ching","ja":"老子『道徳経』","zh":"老子《道德经》","es":"Lao-Tse, Tao Te Ching","pt":"Lao-Tsé, Tao Te Ching","th":"เล่าจื๊อ, คัมภีร์เต้าเต๋อจิง","ar":"لاو تزو، الطاو تي تشينغ","tr":"Lao Tzu, Tao Te Ching","de":"Laotse, Tao te king","fr":"Lao-Tseu, Tao Te King","nl":"Lao Tse, Tao te king","pl":"Laozi, Tao Te Ching","ro":"Lao Zi, Tao Te Ching"}},{"id":77,"t":{"ko":"나는 하루에 세 번 나 자신을 돌아본다.","en":"I daily examine myself on three points.","ja":"吾日に吾が身を三省す。","zh":"吾日三省吾身。","es":"Cada día me examino tres veces a mí mismo.","pt":"Todos os dias examino a mim mesmo três vezes.","th":"ข้าพเจ้าพิจารณาตนเองวันละสามครั้ง","ar":"إني أحاسب نفسي كل يوم ثلاث مرات.","tr":"Her gün kendimi üç kez sorgularım.","de":"Ich prüfe mich täglich dreimal.","fr":"Chaque jour, je m’examine trois fois.","nl":"Elke dag onderzoek ik mezelf driemaal.","pl":"Codziennie trzykrotnie rozważam własne postępowanie.","ro":"În fiecare zi mă cercetez de trei ori."},"by":{"ko":"증자, 『논어』","en":"Zengzi, The Analects","ja":"曾子『論語』","zh":"曾子《论语》","es":"Zengzi, Analectas","pt":"Zengzi, Analectos","th":"เจิงจื่อ, คัมภีร์หลุนอวี่","ar":"تسنغ تسي، مختارات كونفوشيوس","tr":"Zengzi, Konuşmalar","de":"Zengzi, Gespräche des Konfuzius (Lunyu)","fr":"Zengzi, Entretiens de Confucius","nl":"Zengzi, Analecten van Confucius","pl":"Zengzi, Dialogi konfucjańskie","ro":"Zengzi, Analectele lui Confucius"}},{"id":78,"t":{"ko":"성찰하지 않는 삶은 살 가치가 없다.","en":"The unexamined life is not worth living.","ja":"吟味されない生は、生きるに値しない。","zh":"未经审视的人生不值得过。","es":"Una vida sin examen no merece ser vivida.","pt":"A vida não examinada não vale a pena ser vivida.","th":"ชีวิตที่ไม่ได้ใคร่ครวญ ไม่ควรค่าแก่การมีชีวิตอยู่","ar":"الحياة التي لا تخضع للفحص لا تستحق أن تُعاش.","tr":"Sorgulanmamış bir hayat yaşanmaya değmez.","de":"Ein Leben ohne Selbsterforschung ist nicht lebenswert.","fr":"Une vie sans examen ne vaut pas la peine d’être vécue.","nl":"Een leven zonder zelfonderzoek is het niet waard geleefd te worden.","pl":"Życie bez refleksji nie jest warte życia.","ro":"O viață necercetată nu merită trăită."},"by":{"ko":"소크라테스, 플라톤 『소크라테스의 변명』","en":"Socrates, in Plato’s Apology","ja":"ソクラテス（プラトン『ソクラテスの弁明』）","zh":"苏格拉底（柏拉图《苏格拉底的申辩》）","es":"Sócrates, Apología de Sócrates","pt":"Sócrates, Apologia de Sócrates","th":"โสกราตีส, คำแก้ต่างของโสกราตีส","ar":"سقراط، دفاع سقراط","tr":"Sokrates, Sokrates'in Savunması","de":"Sokrates, Apologie des Sokrates","fr":"Socrate, Apologie de Socrate","nl":"Socrates, Apologie (Plato)","pl":"Sokrates, Obrona Sokratesa","ro":"Socrate, Apărarea lui Socrate"}},{"id":79,"t":{"ko":"우리의 삶은 우리의 생각이 만든다.","en":"Our life is what our thoughts make it.","ja":"我々の人生は、我々の思考がつくるものである。","zh":"我们的生活，是由我们的思想造就的。","es":"Nuestra vida es lo que nuestros pensamientos hacen de ella.","pt":"Nossa vida é aquilo que nossos pensamentos fazem dela.","th":"ชีวิตของเราเป็นอย่างที่ความคิดของเราสร้างขึ้น","ar":"حياتنا من صنع أفكارنا.","tr":"Hayatımız, düşüncelerimizin eseridir.","de":"Unser Leben ist das, wozu unsere Gedanken es machen.","fr":"Notre vie est ce que nos pensées en font.","nl":"Ons leven is wat onze gedachten ervan maken.","pl":"Nasze życie jest takie, jakim czynią je nasze myśli.","ro":"Viața noastră este ceea ce fac din ea gândurile noastre."},"by":{"ko":"마르쿠스 아우렐리우스, 『명상록』","en":"Marcus Aurelius, Meditations","ja":"マルクス・アウレリウス『自省録』","zh":"马可·奥勒留《沉思录》","es":"Marco Aurelio, Meditaciones","pt":"Marco Aurélio, Meditações","th":"มาร์คัส ออเรลิอัส, บันทึกใคร่ครวญ (Meditations)","ar":"ماركوس أوريليوس، التأملات","tr":"Marcus Aurelius, Kendime Düşünceler","de":"Mark Aurel, Selbstbetrachtungen","fr":"Marc Aurèle, Pensées pour moi-même","nl":"Marcus Aurelius, Overpeinzingen","pl":"Marek Aureliusz, Rozmyślania","ro":"Marcus Aurelius, Gânduri către sine însuși"}},{"id":80,"t":{"ko":"지금 바로 살기 시작하라. 하루하루를 하나의 삶으로 여겨라.","en":"Begin at once to live, and count each separate day as a separate life.","ja":"今すぐ生きはじめよ。一日一日を、それぞれ一つの人生として数えよ。","zh":"立刻开始生活吧，把每一天都当作独立的一生。","es":"Empieza a vivir ahora mismo y cuenta cada día como una vida.","pt":"Comece a viver agora mesmo e conte cada dia como uma vida.","th":"จงเริ่มใช้ชีวิตเสียตั้งแต่บัดนี้ และนับแต่ละวันเสมือนชีวิตหนึ่ง","ar":"ابدأ الحياة فورًا، واعتبر كل يوم حياةً قائمة بذاتها.","tr":"Hemen yaşamaya başla ve her günü ayrı bir hayat say.","de":"Fange gleich an zu leben und zähle jeden einzelnen Tag als ein eigenes Leben.","fr":"Hâte-toi de bien vivre et songe que chaque jour est à lui seul une vie.","nl":"Begin meteen te leven en beschouw elke dag als een afzonderlijk leven.","pl":"Zacznij żyć od zaraz i każdy dzień traktuj jak osobne życie.","ro":"Începe chiar acum să trăiești și socotește fiecare zi drept o viață în sine."},"by":{"ko":"세네카, 『도덕 서한』","en":"Seneca, Letters to Lucilius","ja":"セネカ『ルキリウスへの手紙』","zh":"塞涅卡《道德书简》","es":"Séneca, Cartas a Lucilio","pt":"Sêneca, Cartas a Lucílio","th":"เซเนกา, จดหมายว่าด้วยศีลธรรม","ar":"سينيكا، رسائل أخلاقية","tr":"Seneca, Ahlak Üzerine Mektuplar","de":"Seneca, Briefe an Lucilius","fr":"Sénèque, Lettres à Lucilius","nl":"Seneca, Brieven aan Lucilius","pl":"Seneka, Listy moralne do Lucyliusza","ro":"Seneca, Scrisori către Lucilius"}},{"id":81,"t":{"ko":"종이는 사람보다 참을성이 많다.","en":"Paper has more patience than people.","ja":"紙は人間よりも辛抱強い。","zh":"纸比人更有耐心。","es":"El papel es más paciente que los hombres.","pt":"O papel tem mais paciência do que as pessoas.","th":"กระดาษมีความอดทนมากกว่าคน","ar":"الورق أكثر صبرًا من البشر.","tr":"Kâğıt insanlardan daha sabırlıdır.","de":"Papier ist geduldiger als Menschen.","fr":"Le papier est plus patient que les hommes.","nl":"Papier is geduldiger dan de mensen.","pl":"Papier jest cierpliwszy niż ludzie.","ro":"Hârtia e mai răbdătoare decât oamenii."},"by":{"ko":"안네 프랑크, 『안네의 일기』","en":"Anne Frank, The Diary of a Young Girl","ja":"アンネ・フランク『アンネの日記』","zh":"安妮·弗兰克《安妮日记》","es":"Ana Frank, Diario de Ana Frank","pt":"Anne Frank, O Diário de Anne Frank","th":"แอนน์ แฟรงค์, บันทึกลับของแอนน์ แฟรงค์","ar":"آن فرانك، يوميات آن فرانك","tr":"Anne Frank, Anne Frank'ın Hatıra Defteri","de":"Anne Frank, Das Tagebuch der Anne Frank","fr":"Anne Frank, Le Journal d’Anne Frank","nl":"Anne Frank, Het Achterhuis","pl":"Anne Frank, Dziennik","ro":"Anne Frank, Jurnalul Annei Frank"}},{"id":82,"t":{"ko":"글을 쓰면 모든 것을 떨쳐 낼 수 있다. 슬픔은 사라지고 용기가 다시 생긴다.","en":"I can shake off everything as I write; my sorrows disappear, my courage is reborn.","ja":"書いていれば、なにもかも振り払うことができる。悲しみは消え、勇気がよみがえる。","zh":"写作时，我能摆脱一切；悲伤消失，勇气重生。","es":"Cuando escribo se me pasa todo: mis penas desaparecen, mi valentía revive.","pt":"Quando escrevo, consigo me livrar de tudo. Minha tristeza desaparece, minha coragem renasce.","th":"เมื่อได้เขียน ฉันสลัดทุกอย่างทิ้งไปได้ ความเศร้าหายไป ความกล้าก็กลับมาอีกครั้ง","ar":"حين أكتب أستطيع أن أتخلّص من كل شيء؛ تزول أحزاني وتولد شجاعتي من جديد.","tr":"Yazarken her şeyden kurtulabiliyorum; üzüntülerim kayboluyor, cesaretim yeniden doğuyor.","de":"Wenn ich schreibe, kann ich alles abschütteln. Mein Kummer verschwindet, mein Mut lebt wieder auf.","fr":"Quand j’écris, je me débarrasse de tout : mon chagrin disparaît, mon courage renaît.","nl":"Als ik schrijf kan ik alles van me afschudden, mijn verdriet verdwijnt, mijn moed herleeft!","pl":"Kiedy piszę, mogę wszystko z siebie strząsnąć. Smutek znika, a odwaga się odradza.","ro":"Când scriu, pot să mă scutur de toate. Tristețea dispare, curajul renaște."},"by":{"ko":"안네 프랑크, 『안네의 일기』","en":"Anne Frank, The Diary of a Young Girl","ja":"アンネ・フランク『アンネの日記』","zh":"安妮·弗兰克《安妮日记》","es":"Ana Frank, Diario de Ana Frank","pt":"Anne Frank, O Diário de Anne Frank","th":"แอนน์ แฟรงค์, บันทึกลับของแอนน์ แฟรงค์","ar":"آن فرانك، يوميات آن فرانك","tr":"Anne Frank, Anne Frank'ın Hatıra Defteri","de":"Anne Frank, Das Tagebuch der Anne Frank","fr":"Anne Frank, Le Journal d’Anne Frank","nl":"Anne Frank, Het Achterhuis","pl":"Anne Frank, Dziennik","ro":"Anne Frank, Jurnalul Annei Frank"}},{"id":83,"t":{"ko":"매일이 한 해 중 가장 좋은 날임을 마음에 새겨라.","en":"Write it on your heart that every day is the best day in the year.","ja":"毎日が一年でいちばん良い日だと、心に刻みなさい。","zh":"把这句话写在心上：每一天都是一年中最好的一天。","es":"Escribe en tu corazón que cada día es el mejor día del año.","pt":"Escreva em seu coração que cada dia é o melhor dia do ano.","th":"จงจารึกไว้ในใจว่า ทุกวันคือวันที่ดีที่สุดของปี","ar":"انقش في قلبك أن كل يوم هو أفضل يوم في السنة.","tr":"Her günün yılın en güzel günü olduğunu yüreğine yaz.","de":"Schreib dir ins Herz, dass jeder Tag der beste des Jahres ist.","fr":"Écrivez dans votre cœur que chaque jour est le meilleur de l’année.","nl":"Schrijf in je hart dat elke dag de beste dag van het jaar is.","pl":"Zapisz w sercu, że każdy dzień jest najlepszym dniem w roku.","ro":"Scrie-ți în inimă că fiecare zi este cea mai bună zi din an."},"by":{"ko":"랄프 왈도 에머슨","en":"Ralph Waldo Emerson","ja":"ラルフ・ウォルド・エマソン","zh":"拉尔夫·沃尔多·爱默生","es":"Ralph Waldo Emerson","pt":"Ralph Waldo Emerson","th":"ราล์ฟ วอลโด เอเมอร์สัน","ar":"رالف والدو إمرسون","tr":"Ralph Waldo Emerson","de":"Ralph Waldo Emerson","fr":"Ralph Waldo Emerson","nl":"Ralph Waldo Emerson","pl":"Ralph Waldo Emerson","ro":"Ralph Waldo Emerson"}},{"id":84,"t":{"ko":"하루를 마쳤으면 그것으로 끝내라. 너는 할 수 있는 일을 다 했다.","en":"Finish each day and be done with it. You have done what you could.","ja":"一日を終えたら、それで終わりにしなさい。できることはやったのだから。","zh":"每一天结束了，就让它过去吧。你已经尽力了。","es":"Termina cada día y olvídate de él. Hiciste lo que pudiste.","pt":"Termine cada dia e dê-o por encerrado. Você fez o que pôde.","th":"เมื่อจบวันหนึ่งแล้วก็ปล่อยมันไป เราทำเท่าที่ทำได้แล้ว","ar":"أنهِ كل يوم وانتهِ منه. لقد فعلت ما استطعت.","tr":"Her günü tamamla ve geride bırak. Elinden geleni yaptın.","de":"Beende jeden Tag und schließe damit ab. Du hast getan, was du konntest.","fr":"Terminez chaque journée et tournez la page. Vous avez fait ce que vous pouviez.","nl":"Sluit elke dag af en laat hem achter je. Je hebt gedaan wat je kon.","pl":"Kończ każdy dzień i zostaw go za sobą. Co było w twojej mocy, zostało zrobione.","ro":"Încheie fiecare zi și las-o în urmă. Ai făcut ce ai putut."},"by":{"ko":"랄프 왈도 에머슨","en":"Ralph Waldo Emerson","ja":"ラルフ・ウォルド・エマソン","zh":"拉尔夫·沃尔多·爱默生","es":"Ralph Waldo Emerson","pt":"Ralph Waldo Emerson","th":"ราล์ฟ วอลโด เอเมอร์สัน","ar":"رالف والدو إمرسون","tr":"Ralph Waldo Emerson","de":"Ralph Waldo Emerson","fr":"Ralph Waldo Emerson","nl":"Ralph Waldo Emerson","pl":"Ralph Waldo Emerson","ro":"Ralph Waldo Emerson"}},{"id":85,"t":{"ko":"오늘 나는 어떤 좋은 일을 했는가?","en":"What good have I done today?","ja":"今日、私はどんな善いことをしたか？","zh":"今天我做了什么好事？","es":"¿Qué bien he hecho hoy?","pt":"Que bem eu fiz hoje?","th":"วันนี้ฉันได้ทำความดีอะไรบ้าง","ar":"ما الخير الذي فعلته اليوم؟","tr":"Bugün ne iyilik yaptım?","de":"Was habe ich heute Gutes getan?","fr":"Quel bien ai-je fait aujourd’hui ?","nl":"Wat voor goeds heb ik vandaag gedaan?","pl":"Co dobrego dziś zrobiłem?","ro":"Ce lucru bun am făcut astăzi?"},"by":{"ko":"벤저민 프랭클린, 『프랭클린 자서전』","en":"Benjamin Franklin, The Autobiography of Benjamin Franklin","ja":"ベンジャミン・フランクリン『フランクリン自伝』","zh":"本杰明·富兰克林《富兰克林自传》","es":"Benjamin Franklin, Autobiografía","pt":"Benjamin Franklin, Autobiografia","th":"เบนจามิน แฟรงคลิน, อัตชีวประวัติ","ar":"بنجامين فرانكلين، السيرة الذاتية","tr":"Benjamin Franklin, Otobiyografi","de":"Benjamin Franklin, Autobiographie","fr":"Benjamin Franklin, Autobiographie","nl":"Benjamin Franklin, Autobiografie","pl":"Benjamin Franklin, Autobiografia","ro":"Benjamin Franklin, Autobiografia"}},{"id":86,"t":{"ko":"내가 숲으로 간 것은 신중하게 살고 싶었기 때문이다.","en":"I went to the woods because I wished to live deliberately.","ja":"私が森へ行ったのは、思慮深く生きたかったからだ。","zh":"我到林中去，因为我希望谨慎地生活。","es":"Fui a los bosques porque quería vivir deliberadamente.","pt":"Fui para os bosques porque queria viver deliberadamente.","th":"ฉันไปอยู่ในป่าเพราะปรารถนาจะใช้ชีวิตอย่างตั้งใจ","ar":"ذهبت إلى الغابة لأنني أردت أن أعيش بوعي.","tr":"Ormana gittim, çünkü bilinçli yaşamak istiyordum.","de":"Ich ging in die Wälder, weil ich bewusst leben wollte.","fr":"Je suis allé dans les bois parce que je voulais vivre délibérément.","nl":"Ik ging naar de bossen omdat ik bewust wilde leven.","pl":"Poszedłem do lasu, ponieważ chciałem żyć świadomie.","ro":"M-am dus în pădure pentru că voiam să trăiesc conștient."},"by":{"ko":"헨리 데이비드 소로, 『월든』","en":"Henry David Thoreau, Walden","ja":"ヘンリー・D・ソロー『森の生活（ウォールデン）』","zh":"亨利·戴维·梭罗《瓦尔登湖》","es":"Henry David Thoreau, Walden","pt":"Henry David Thoreau, Walden","th":"เฮนรี เดวิด ธอโร, วอลเดน","ar":"هنري ديفيد ثورو، والدن","tr":"Henry David Thoreau, Walden","de":"Henry David Thoreau, Walden","fr":"Henry David Thoreau, Walden ou la Vie dans les bois","nl":"Henry David Thoreau, Walden","pl":"Henry David Thoreau, Walden, czyli życie w lesie","ro":"Henry David Thoreau, Walden"}},{"id":87,"t":{"ko":"나는 다른 무엇보다 나 자신을 연구한다.","en":"I study myself more than any other subject.","ja":"私は他の何よりも、自分自身を研究する。","zh":"我研究自己，胜过研究任何其他事物。","es":"Me estudio a mí mismo más que a ningún otro tema.","pt":"Estudo a mim mesmo mais do que a qualquer outro assunto.","th":"ฉันศึกษาตัวเองมากกว่าเรื่องอื่นใด","ar":"أدرس نفسي أكثر من أي موضوع آخر.","tr":"Kendimi her şeyden çok incelerim.","de":"Ich studiere mich selbst mehr als jeden anderen Gegenstand.","fr":"Je m’étudie plus qu’autre sujet.","nl":"Ik bestudeer mezelf meer dan enig ander onderwerp.","pl":"Badam siebie bardziej niż cokolwiek innego.","ro":"Mă studiez pe mine însumi mai mult decât orice alt subiect."},"by":{"ko":"몽테뉴, 『수상록』","en":"Michel de Montaigne, Essays","ja":"モンテーニュ『エセー』","zh":"蒙田《随笔集》","es":"Michel de Montaigne, Ensayos","pt":"Michel de Montaigne, Ensaios","th":"มงแตญ, ความเรียง","ar":"مونتين، المقالات","tr":"Montaigne, Denemeler","de":"Michel de Montaigne, Essais","fr":"Michel de Montaigne, Essais","nl":"Michel de Montaigne, Essays","pl":"Michel de Montaigne, Próby","ro":"Michel de Montaigne, Eseuri"}},{"id":88,"t":{"ko":"가장 중요한 것은 눈에 보이지 않아.","en":"What is essential is invisible to the eye.","ja":"大切なものは、目に見えない。","zh":"真正重要的东西，用眼睛是看不见的。","es":"Lo esencial es invisible a los ojos.","pt":"O essencial é invisível aos olhos.","th":"สิ่งสำคัญนั้นไม่อาจมองเห็นได้ด้วยตา","ar":"الجوهري لا تراه العيون.","tr":"Asıl önemli olan gözle görülmez.","de":"Das Wesentliche ist für die Augen unsichtbar.","fr":"L’essentiel est invisible pour les yeux.","nl":"Het wezenlijke is voor de ogen onzichtbaar.","pl":"Najważniejsze jest niewidoczne dla oczu.","ro":"Esențialul este invizibil pentru ochi."},"by":{"ko":"생텍쥐페리, 『어린 왕자』","en":"Antoine de Saint-Exupéry, The Little Prince","ja":"サン＝テグジュペリ『星の王子さま』","zh":"圣埃克苏佩里《小王子》","es":"Antoine de Saint-Exupéry, El principito","pt":"Antoine de Saint-Exupéry, O Pequeno Príncipe","th":"อองตวน เดอ แซงเตกซูเปรี, เจ้าชายน้อย","ar":"أنطوان دو سانت إكزوبيري، الأمير الصغير","tr":"Antoine de Saint-Exupéry, Küçük Prens","de":"Antoine de Saint-Exupéry, Der kleine Prinz","fr":"Antoine de Saint-Exupéry, Le Petit Prince","nl":"Antoine de Saint-Exupéry, De kleine prins","pl":"Antoine de Saint-Exupéry, Mały Książę","ro":"Antoine de Saint-Exupéry, Micul Prinț"}},{"id":89,"t":{"ko":"어제로 돌아가 봐야 소용없어. 그때의 나는 다른 사람이었으니까.","en":"It’s no use going back to yesterday, because I was a different person then.","ja":"昨日に戻ってもしかたないわ。だって、あのときの私は別人だったもの。","zh":"回到昨天是没有用的，因为那时的我是另一个人。","es":"No sirve de nada volver a ayer, porque entonces yo era una persona distinta.","pt":"Não adianta voltar para ontem, porque eu era uma pessoa diferente naquela época.","th":"ย้อนกลับไปเมื่อวานก็ไม่มีประโยชน์ เพราะตอนนั้นฉันเป็นอีกคนหนึ่ง","ar":"لا فائدة من العودة إلى الأمس، لأنني كنت شخصًا مختلفًا حينها.","tr":"Düne dönmenin faydası yok, çünkü o zaman başka biriydim.","de":"Es hat keinen Sinn, zu gestern zurückzugehen, denn da war ich ein anderer Mensch.","fr":"Inutile de revenir à hier, car j’étais alors une autre personne.","nl":"Het heeft geen zin om terug te gaan naar gisteren, want toen was ik iemand anders.","pl":"Nie ma sensu wracać do wczoraj, bo wtedy byłam kimś innym.","ro":"N-are rost să mă întorc la ziua de ieri, pentru că atunci eram altcineva."},"by":{"ko":"루이스 캐럴, 『이상한 나라의 앨리스』","en":"Lewis Carroll, Alice’s Adventures in Wonderland","ja":"ルイス・キャロル『不思議の国のアリス』","zh":"刘易斯·卡罗尔《爱丽丝梦游仙境》","es":"Lewis Carroll, Alicia en el país de las maravillas","pt":"Lewis Carroll, Alice no País das Maravilhas","th":"ลูอิส แคร์รอลล์, อลิซในแดนมหัศจรรย์","ar":"لويس كارول، أليس في بلاد العجائب","tr":"Lewis Carroll, Alice Harikalar Diyarında","de":"Lewis Carroll, Alice im Wunderland","fr":"Lewis Carroll, Alice au pays des merveilles","nl":"Lewis Carroll, Alice in Wonderland","pl":"Lewis Carroll, Alicja w Krainie Czarów","ro":"Lewis Carroll, Alice în Țara Minunilor"}},{"id":90,"t":{"ko":"내일은 아직 아무 실수도 하지 않은 새로운 날이에요.","en":"Tomorrow is a new day with no mistakes in it yet.","ja":"明日はまだ何ひとつ失敗をしていない、新しい日よ。","zh":"明天是全新的一天，还没有犯任何错误。","es":"Mañana es un día nuevo, todavía sin errores.","pt":"Amanhã é um novo dia, ainda sem nenhum erro.","th":"พรุ่งนี้คือวันใหม่ที่ยังไม่มีความผิดพลาดใดๆ เลย","ar":"الغد يوم جديد لم تُرتكب فيه أي أخطاء بعد.","tr":"Yarın, henüz hiç hata yapılmamış yepyeni bir gün.","de":"Morgen ist ein neuer Tag, noch ganz ohne Fehler.","fr":"Demain est un nouveau jour, encore sans aucune erreur.","nl":"Morgen is een nieuwe dag, nog zonder fouten.","pl":"Jutro jest nowy dzień, jeszcze bez żadnych błędów.","ro":"Mâine e o zi nouă, încă fără nicio greșeală."},"by":{"ko":"루시 모드 몽고메리, 『빨간 머리 앤』","en":"L. M. Montgomery, Anne of Green Gables","ja":"L・M・モンゴメリ『赤毛のアン』","zh":"露西·莫德·蒙哥马利《绿山墙的安妮》","es":"L. M. Montgomery, Ana de las Tejas Verdes","pt":"L. M. Montgomery, Anne de Green Gables","th":"ลูซี มอด มอนต์โกเมอรี, แอนน์แห่งกรีนเกเบิลส์","ar":"لوسي مود مونتغمري، آن في المرتفعات الخضراء","tr":"L. M. Montgomery, Yeşilin Kızı Anne","de":"L. M. Montgomery, Anne auf Green Gables","fr":"L. M. Montgomery, Anne de la Maison aux pignons verts","nl":"L. M. Montgomery, Anne van het Groene Huis","pl":"Lucy Maud Montgomery, Ania z Zielonego Wzgórza","ro":"L. M. Montgomery, Anne de la Green Gables"}},{"id":91,"t":{"ko":"내일은 내일의 태양이 뜰 거야.","en":"After all, tomorrow is another day.","ja":"明日は明日の風が吹く。","zh":"毕竟，明天又是新的一天。","es":"Después de todo, mañana será otro día.","pt":"Afinal, amanhã é outro dia.","th":"อย่างไรเสีย พรุ่งนี้ก็เป็นอีกวันหนึ่ง","ar":"على أي حال، غدًا يوم آخر.","tr":"Ne de olsa yarın başka bir gün.","de":"Morgen ist auch ein Tag.","fr":"Après tout, demain est un autre jour.","nl":"Morgen is er weer een dag.","pl":"Przecież jutro też jest dzień.","ro":"Mâine e o altă zi."},"by":{"ko":"마거릿 미첼, 『바람과 함께 사라지다』","en":"Margaret Mitchell, Gone with the Wind","ja":"マーガレット・ミッチェル『風と共に去りぬ』","zh":"玛格丽特·米切尔《飘》","es":"Margaret Mitchell, Lo que el viento se llevó","pt":"Margaret Mitchell, E o Vento Levou","th":"มาร์กาเร็ต มิตเชลล์, วิมานลอย","ar":"مارغريت ميتشل، ذهب مع الريح","tr":"Margaret Mitchell, Rüzgâr Gibi Geçti","de":"Margaret Mitchell, Vom Winde verweht","fr":"Margaret Mitchell, Autant en emporte le vent","nl":"Margaret Mitchell, Gejaagd door de wind","pl":"Margaret Mitchell, Przeminęło z wiatrem","ro":"Margaret Mitchell, Pe aripile vântului"}},{"id":92,"t":{"ko":"나는 일기 없이는 여행하지 않는다. 기차에서 읽을 흥미진진한 것이 늘 있어야 하니까.","en":"I never travel without my diary. One should always have something sensational to read in the train.","ja":"私は日記なしでは旅をしませんの。汽車の中では、いつも何か刺激的な読み物がなくてはね。","zh":"我出门旅行总要带着日记。在火车上，总得有点耸人听闻的东西读一读。","es":"Nunca viajo sin mi diario. Siempre hay que tener algo sensacional que leer en el tren.","pt":"Nunca viajo sem meu diário. É preciso sempre ter algo sensacional para ler no trem.","th":"ฉันไม่เคยเดินทางโดยไม่มีไดอารี่ เราควรมีอะไรน่าตื่นเต้นไว้อ่านบนรถไฟเสมอ","ar":"لا أسافر أبدًا من دون مذكراتي. يجب أن يكون لدى المرء دائمًا شيء مثير يقرؤه في القطار.","tr":"Günlüğüm olmadan asla yolculuğa çıkmam. İnsanın trende okuyacak heyecanlı bir şeyi olmalı.","de":"Ich reise nie ohne mein Tagebuch. Man sollte im Zug immer etwas Sensationelles zu lesen haben.","fr":"Je ne voyage jamais sans mon journal. Il faut toujours avoir quelque chose de sensationnel à lire dans le train.","nl":"Ik reis nooit zonder mijn dagboek. Je moet in de trein altijd iets sensationeels te lezen hebben.","pl":"Nigdy nie podróżuję bez pamiętnika. W pociągu zawsze trzeba mieć coś sensacyjnego do czytania.","ro":"Nu călătoresc niciodată fără jurnalul meu. Trebuie să ai mereu ceva senzațional de citit în tren."},"by":{"ko":"오스카 와일드, 『진지함의 중요성』","en":"Oscar Wilde, The Importance of Being Earnest","ja":"オスカー・ワイルド『真面目が肝心』","zh":"奥斯卡·王尔德《不可儿戏》","es":"Oscar Wilde, La importancia de llamarse Ernesto","pt":"Oscar Wilde, A Importância de Ser Prudente","th":"ออสการ์ ไวลด์, ความสำคัญของการเป็นเอิร์นเนสต์","ar":"أوسكار وايلد، أهمية أن تكون جادًا","tr":"Oscar Wilde, Ciddi Olmanın Önemi","de":"Oscar Wilde, Bunbury","fr":"Oscar Wilde, L’Importance d’être Constant","nl":"Oscar Wilde, Het belang van Ernst","pl":"Oscar Wilde, Bądźmy poważni na serio","ro":"Oscar Wilde, Ce înseamnă să fii onest"}},{"id":93,"t":{"ko":"죽는 날까지 하늘을 우러러 한 점 부끄럼이 없기를.","en":"Until the day I die, may I look up to heaven without a speck of shame.","ja":"死ぬ日まで空を仰ぎ、一点の恥辱なきことを。","zh":"直到死去的那一天，仰望苍天，愿无一丝愧疚。","es":"Que hasta el día de mi muerte pueda mirar al cielo sin una sola mancha de vergüenza.","pt":"Que até o dia da minha morte eu possa olhar para o céu sem uma só mancha de vergonha.","th":"ขอให้จนวันตาย เงยหน้ามองฟ้าได้โดยไม่มีสิ่งใดให้ละอายแม้เพียงนิด","ar":"ليتني حتى يوم مماتي أرفع عينيّ إلى السماء بلا ذرّة خجل.","tr":"Ölene dek göğe bakıp bir zerre utanç duymamayı dilerim.","de":"Bis zu dem Tag, an dem ich sterbe, möchte ich zum Himmel aufblicken, ohne einen Hauch von Scham.","fr":"Puissé-je, jusqu’au jour de ma mort, lever les yeux vers le ciel sans la moindre honte.","nl":"Tot de dag dat ik sterf wil ik naar de hemel opkijken zonder een zweem van schaamte.","pl":"Obym do dnia śmierci mógł patrzeć w niebo bez cienia wstydu.","ro":"Până în ziua morții, să pot privi cerul fără pic de rușine."},"by":{"ko":"윤동주, 「서시」","en":"Yun Dong-ju, “Prologue”","ja":"尹東柱「序詩」","zh":"尹东柱《序诗》","es":"Yun Dong-ju, «Prólogo»","pt":"Yun Dong-ju, “Prólogo”","th":"ยุน ดงจู, บทนำ (ซอชี)","ar":"يون دونغ جو، المقدّمة (سوسي)","tr":"Yun Dong-ju, Önsöz (Seosi)","de":"Yun Dong-ju, Prolog (Seosi)","fr":"Yun Dong-ju, Prologue","nl":"Yun Dong-ju, Proloog (Seosi)","pl":"Yun Dong-ju, Prolog (Seosi)","ro":"Yun Dong-ju, Prolog (Seosi)"}},{"id":94,"t":{"ko":"시작이 반이다.","en":"Well begun is half done.","ja":"始まりは全体の半分である。","zh":"好的开始是成功的一半。","es":"El comienzo es la mitad del todo.","pt":"O começo é a metade do todo.","th":"เริ่มต้นดีมีชัยไปกว่าครึ่ง","ar":"البداية نصف العمل.","tr":"Başlangıç, bütünün yarısıdır.","de":"Der Anfang ist die Hälfte des Ganzen.","fr":"Le commencement est la moitié du tout.","nl":"Het begin is het halve werk.","pl":"Początek to połowa całości.","ro":"Începutul este jumătate din întreg."},"by":{"ko":"그리스 속담, 아리스토텔레스 『정치학』에서","en":"Greek proverb, quoted in Aristotle’s Politics","ja":"ギリシャのことわざ（アリストテレス『政治学』より）","zh":"希腊谚语，见亚里士多德《政治学》","es":"Proverbio griego, citado en la «Política» de Aristóteles","pt":"Provérbio grego, citado na “Política” de Aristóteles","th":"สุภาษิตกรีก อ้างใน “การเมือง” ของอริสโตเติล","ar":"مثل يوناني، أورده أرسطو في «السياسة»","tr":"Yunan atasözü, Aristoteles’in ‘Politika’ eserinden","de":"Griechisches Sprichwort, zitiert in Aristoteles’ „Politik“","fr":"Proverbe grec, cité dans « La Politique » d’Aristote","nl":"Grieks spreekwoord, geciteerd in Aristoteles’ ‘Politiek’","pl":"Przysłowie greckie, cytowane w „Polityce” Arystotelesa","ro":"Proverb grecesc, citat în „Politica” lui Aristotel"}},{"id":95,"t":{"ko":"위대한 일은 작은 일들이 모여 이루어진다.","en":"Great things are done by a series of small things brought together.","ja":"偉大なことは、小さなことの積み重ねによって成し遂げられる。","zh":"伟大的事业是由一系列小事汇聚而成的。","es":"Las grandes cosas se hacen con una serie de pequeñas cosas reunidas.","pt":"As grandes coisas são feitas por uma série de pequenas coisas reunidas.","th":"สิ่งยิ่งใหญ่เกิดจากสิ่งเล็กๆ หลายสิ่งมารวมกัน","ar":"الأعمال العظيمة تتحقق بسلسلة من الأشياء الصغيرة مجتمعة.","tr":"Büyük işler, bir araya gelen küçük işlerle başarılır.","de":"Große Dinge entstehen aus einer Reihe kleiner Dinge, die zusammenkommen.","fr":"Les grandes choses sont faites d’une série de petites choses réunies.","nl":"Het grote geschiedt niet bij impulsie alleen, maar is een aaneenschakeling van kleine dingen.","pl":"Wielkie rzeczy powstają z szeregu małych rzeczy złożonych w całość.","ro":"Lucrurile mari se fac dintr-o serie de lucruri mici puse laolaltă."},"by":{"ko":"빈센트 반 고흐, 테오에게 보낸 편지","en":"Vincent van Gogh, letter to Theo","ja":"フィンセント・ファン・ゴッホ（テオへの手紙）","zh":"文森特·梵高（致提奥的信）","es":"Vincent van Gogh, carta a Theo","pt":"Vincent van Gogh, carta a Theo","th":"วินเซนต์ แวน โก๊ะ, จดหมายถึงเทโอ","ar":"فنسنت فان غوخ، رسالة إلى ثيو","tr":"Vincent van Gogh, Theo'ya mektup","de":"Vincent van Gogh, Brief an Theo","fr":"Vincent van Gogh, lettre à Théo","nl":"Vincent van Gogh, brief aan Theo","pl":"Vincent van Gogh, list do Theo","ro":"Vincent van Gogh, scrisoare către Theo"}},{"id":96,"t":{"ko":"가장 중요한 때는 바로 지금이다.","en":"The most important time is now.","ja":"いちばん大切な時は、今である。","zh":"最重要的时间就是现在。","es":"El momento más importante es ahora.","pt":"O momento mais importante é agora.","th":"เวลาที่สำคัญที่สุดคือตอนนี้","ar":"أهم وقت هو الآن.","tr":"En önemli zaman şimdidir.","de":"Die wichtigste Zeit ist jetzt.","fr":"Le moment le plus important, c’est maintenant.","nl":"De belangrijkste tijd is nu.","pl":"Najważniejszy czas to teraz.","ro":"Cel mai important timp este acum."},"by":{"ko":"톨스토이, 「세 가지 질문」","en":"Leo Tolstoy, “Three Questions”","ja":"トルストイ「三つの問い」","zh":"托尔斯泰《三个问题》","es":"León Tolstói, «Las tres preguntas»","pt":"Liev Tolstói, “As Três Perguntas”","th":"ลีโอ ตอลสตอย, คำถามสามข้อ","ar":"ليو تولستوي، الأسئلة الثلاثة","tr":"Lev Tolstoy, Üç Soru","de":"Leo Tolstoi, Drei Fragen","fr":"Léon Tolstoï, Les Trois Questions","nl":"Lev Tolstoj, Drie vragen","pl":"Lew Tołstoj, Trzy pytania","ro":"Lev Tolstoi, Trei întrebări"}},{"id":97,"t":{"ko":"배우고 때때로 익히면 또한 기쁘지 아니한가.","en":"Is it not a pleasure to learn and to practice what you have learned?","ja":"学びて時に之を習う、亦た説ばしからずや。","zh":"学而时习之，不亦说乎？","es":"Aprender y practicar a su tiempo lo aprendido, ¿no es acaso un placer?","pt":"Aprender e, no tempo certo, praticar o que se aprendeu: não é isso um prazer?","th":"ศึกษาแล้วหมั่นทบทวนอยู่เสมอ มิใช่เรื่องน่ายินดีหรอกหรือ","ar":"أليس من دواعي السرور أن يتعلّم المرء ثم يراجع ما تعلّمه بين حين وآخر؟","tr":"Öğrenip öğrendiğini zaman zaman tekrarlamak insana sevinç vermez mi?","de":"Lernen und fortwährend üben, ist das nicht auch befriedigend?","fr":"Apprendre et, le moment venu, mettre en pratique ce qu’on a appris, n’est-ce pas une joie ?","nl":"Leren en het geleerde steeds weer oefenen, is dat niet een vreugde?","pl":"Uczyć się i stale powtarzać to, czego się nauczyło – czyż to nie przyjemność?","ro":"A învăța și a repeta mereu ce ai învățat, nu e oare o bucurie?"},"by":{"ko":"공자, 『논어』","en":"Confucius, The Analects","ja":"孔子『論語』","zh":"孔子《论语》","es":"Confucio, Analectas","pt":"Confúcio, Analectos","th":"ขงจื๊อ, คัมภีร์หลุนอวี่","ar":"كونفوشيوس، المختارات","tr":"Konfüçyüs, Konuşmalar","de":"Konfuzius, Gespräche (Lunyu)","fr":"Confucius, Entretiens","nl":"Confucius, Analecten","pl":"Konfucjusz, Dialogi konfucjańskie","ro":"Confucius, Analectele"}},{"id":98,"t":{"ko":"우리가 반복해서 하는 것이 곧 우리다.","en":"We are what we repeatedly do.","ja":"私たちは、繰り返し行うことそのものである。","zh":"我们反复做的事，造就了我们。","es":"Somos lo que hacemos repetidamente.","pt":"Nós somos aquilo que fazemos repetidamente.","th":"เราคือสิ่งที่เราทำซ้ำๆ","ar":"نحن ما نفعله بشكل متكرر.","tr":"Biz, tekrar tekrar yaptığımız şeyleriz.","de":"Wir sind, was wir wiederholt tun.","fr":"Nous sommes ce que nous faisons de manière répétée.","nl":"Wij zijn wat we herhaaldelijk doen.","pl":"Jesteśmy tym, co wielokrotnie robimy.","ro":"Suntem ceea ce facem în mod repetat."},"by":{"ko":"윌 듀런트, 『철학 이야기』","en":"Will Durant, The Story of Philosophy","ja":"ウィル・デュラント『哲学の物語』","zh":"威尔·杜兰特《哲学的故事》","es":"Will Durant, sobre Aristóteles","pt":"Will Durant, sobre Aristóteles","th":"วิล ดูแรนต์, เรื่องราวของปรัชญา (ว่าด้วยอริสโตเติล)","ar":"ويل ديورانت، قصة الفلسفة (عن أرسطو)","tr":"Will Durant, Felsefenin Öyküsü (Aristoteles üzerine)","de":"Will Durant, über Aristoteles","fr":"Will Durant, à propos d’Aristote","nl":"Will Durant, over Aristoteles","pl":"Will Durant, o Arystotelesie","ro":"Will Durant, despre Aristotel"}},{"id":99,"t":{"ko":"나를 죽이지 못하는 것은 나를 더 강하게 만든다.","en":"What does not kill me makes me stronger.","ja":"私を殺さないものは、私をより強くする。","zh":"凡不能毁灭我的，必使我更强大。","es":"Lo que no me mata me hace más fuerte.","pt":"O que não me mata me fortalece.","th":"สิ่งที่ไม่ฆ่าเรา จะทำให้เราแข็งแกร่งขึ้น","ar":"ما لا يقتلني يجعلني أقوى.","tr":"Beni öldürmeyen şey güçlendirir.","de":"Was mich nicht umbringt, macht mich stärker.","fr":"Ce qui ne me tue pas me rend plus fort.","nl":"Wat mij niet doodt, maakt mij sterker.","pl":"Co mnie nie zabije, to mnie wzmocni.","ro":"Ce nu mă ucide mă face mai puternic."},"by":{"ko":"니체, 『우상의 황혼』","en":"Friedrich Nietzsche, Twilight of the Idols","ja":"ニーチェ『偶像の黄昏』","zh":"尼采《偶像的黄昏》","es":"Friedrich Nietzsche, Crepúsculo de los ídolos","pt":"Friedrich Nietzsche, Crepúsculo dos Ídolos","th":"ฟรีดริช นีทเชอ, สนธยาแห่งเทวรูป","ar":"فريدريش نيتشه، أفول الأصنام","tr":"Friedrich Nietzsche, Putların Alacakaranlığı","de":"Friedrich Nietzsche, Götzen-Dämmerung","fr":"Friedrich Nietzsche, Le Crépuscule des idoles","nl":"Friedrich Nietzsche, Afgodenschemering","pl":"Friedrich Nietzsche, Zmierzch bożyszcz","ro":"Friedrich Nietzsche, Amurgul idolilor"}},{"id":100,"t":{"ko":"이순신 장군은 전쟁터에서도 하루하루를 일기로 남겼어요.","en":"Admiral Yi Sun-sin kept a diary every day, even on the battlefield.","ja":"李舜臣は戦場でも、一日一日を日記に書き残しました。","zh":"李舜臣将军即使在战场上，也每天写日记。","es":"El almirante Yi Sun-sin escribió su diario día a día, incluso en plena guerra.","pt":"O almirante Yi Sun-sin escreveu seu diário dia após dia, mesmo em plena guerra.","th":"แม่ทัพเรืออีซุนชินยังคงเขียนบันทึกทุกวัน แม้อยู่ในสนามรบ","ar":"كان الأميرال يي سون شين يكتب يومياته يومًا بيوم، حتى في ساحة الحرب.","tr":"Amiral Yi Sun-sin savaşın ortasında bile her gün günlük tuttu.","de":"Admiral Yi Sun-sin führte selbst im Krieg Tag für Tag Tagebuch.","fr":"L’amiral Yi Sun-sin a tenu son journal jour après jour, même en pleine guerre.","nl":"Admiraal Yi Sun-sin hield zelfs midden in de oorlog dag na dag een dagboek bij.","pl":"Admirał Yi Sun-sin prowadził dziennik dzień po dniu, nawet w czasie wojny.","ro":"Amiralul Yi Sun-sin și-a ținut jurnalul zi de zi, chiar și în război."},"by":{"ko":"『난중일기』","en":"Nanjung Ilgi (War Diary)","ja":"『乱中日記』","zh":"《乱中日记》","es":"«Nanjung Ilgi» (Diario de guerra)","pt":"“Nanjung Ilgi” (Diário de guerra)","th":"“นันจุงอิลกี” (บันทึกสงคราม)","ar":"«نانجونغ إلغي» (يوميات الحرب)","tr":"‘Nanjung Ilgi’ (Savaş Günlüğü)","de":"„Nanjung Ilgi“ (Kriegstagebuch)","fr":"« Nanjung Ilgi » (Journal de guerre)","nl":"‘Nanjung Ilgi’ (Oorlogsdagboek)","pl":"„Nanjung Ilgi” (Dziennik wojenny)","ro":"„Nanjung Ilgi” (Jurnal de război)"}}];
